// 此文件由 scripts/import_scanned_history.py 生成，请勿手工编辑。
export const QUESTIONS_2018 = [{"id":"2018-U0-001","unit":0,"number":1,"type":"A1/A2","stem":"五行之中,其特性为“炎上”的是","options":{"A":"木","B":"金","C":"火","D":"水","E":"土"},"answer":"C","explanation":"“火曰炎上”:“炎”,焚烧、炎热、光明之义:“上”,是上升。炎上,是指火具有炎热、上升、光明的特性。引申为凡具有温热、上升、光明等性质或作用的事物和现象,归属于火。"},{"id":"2018-U0-002","unit":0,"number":2,"type":"A1/A2","stem":"依据五行相克规律,下列说法正确的是","options":{"A":"悲胜恐","B":"悲胜喜","C":"恐胜喜","D":"怒胜喜","E":"恐胜思"},"answer":"C","explanation":"怒伤肝,悲胜怒:喜伤心,恐胜喜:思伤脾,怒胜思;忧伤肺,喜胜忧;恐伤肾,思胜恐。"},{"id":"2018-U0-003","unit":0,"number":3,"type":"A1/A2","stem":"下列各项,与心有关的是","options":{"A":"生之本","B":"气之本","C":"后天之本","D":"先天之本","E":"罢极之本"},"answer":"A","explanation":"《素问·六节藏象论》说:“心者,生之本,神之变也。"},{"id":"2018-U0-004","unit":0,"number":4,"type":"A1/A2","stem":"下列各项，具有统血功能的是","options":{"A":"肾","B":"肺","C":"肝","D":"心","E":"脾"},"answer":"E","explanation":"脾主统血指脾气具有统摄、控制血液在脉中正常运行而不逸出脉外的作用。"},{"id":"2018-U0-005","unit":0,"number":5,"type":"A1/A2","stem":"下列各项,具有司眼睑开合作用的是","options":{"A":"督脉","B":"冲脉","C":"任脉","D":"跷脉","E":"带脉"},"answer":"D","explanation":"跷脉的基本功能:一.主司下肢运动:具有交通一身阴阳之气和调节肢体肌肉运动的作用,主要使下肢运动灵活。@司眼睑开合:阴阳跷脉有司眼睑开合的作用,跷脉有病则目不合。"},{"id":"2018-U0-006","unit":0,"number":6,"type":"A1/A2","stem":"六淫致病,其性干涩,易伤津液的是","options":{"A":"风邪","B":"寒邪","C":"暑邪","D":"燥邪","E":"火邪"},"answer":"D","explanation":"燥性干涩,易伤津液:燥邪为多发于秋季的干燥涩滞之病邪,侵犯人体,最易损耗津液,出现各种干燥、涩滞的症状,如口燥咽干,皮肤干涩。"},{"id":"2018-U0-007","unit":0,"number":7,"type":"A1/A2","stem":"《素问·举痛论》认为劳力过度可导致的是","options":{"A":"气上","B":"气泄","C":"气收","D":"气耗","E":"气下"},"answer":"D","explanation":"《素问·举痛论》说:“劳则气耗。”劳伤筋骨,长时间用力太过,则致形体组织损伤,久而积劳成疾。"},{"id":"2018-U0-008","unit":0,"number":8,"type":"A1/A2","stem":"&下列各项,不属于瘀血致病症状特点的是","options":{"A":"痛处固定","B":"爪甲紫暗","C":"肌肤甲错","D":"夜间痛甚","E":"疼痛胀满"},"answer":"E","explanation":"瘀血致病的症状特点:.疼痛:多为刺痛,痛处固定不移,拒按,夜间痛甚。@肿筮及详解块:瘀血积于皮下或体内则可见肿块,肿块部位固定。0出血。@色紫暗:一是面色紫暗,口唇、爪甲青紫等:二是舌质紫黯,或舌有瘀斑、瘀点等。0可出现肌肤甲错,脉涩或脉结代等。"},{"id":"2018-U0-009","unit":0,"number":9,"type":"A1/A2","stem":"热结旁流的病机是","options":{"A":"真虚假实","B":"因虚致实","C":"由实转虚","D":"真实假虚","E":"实中夹虚"},"answer":"D","explanation":"真实假虚:指病机的本质为“实”但表现出“虚”的假象。大多是因邪气过盛,结聚体内,阻滞经络,气血不能外达所致,故真实假虚又称为“大实有羸状”。如因瘀血内阻而出现的妇女崩漏下血,热结肠胃而见泻下稀水臭秽的“热结旁流”等。"},{"id":"2018-U0-010","unit":0,"number":10,"type":"A1/A2","stem":"阳偏衰所形成的证候性质是","options":{"A":"实热","B":"实寒","C":"虚热","D":"虚寒","E":"真热假寒"},"answer":"D","explanation":"阳偏衰即阳虚,指机体阳气虚损,温煦、推动、兴奋等作用减退,出现机能减退或衰弱,代谢减缓,产热不足的病理变化。一般而言,其病机特点多表现为阳气不足,阳不制阴,.阴气相对偏亢的虚寒证。"},{"id":"2018-U0-011","unit":0,"number":11,"type":"A1/A2","stem":"II.下列各项,与气逆的发生有密切关系的是","options":{"A":"心、脾、肾","B":"心、肝、肾","C":"肺、肝、胃","D":"肺、脾、肾","E":"肝、胃、三焦"},"answer":"C","explanation":"气逆:指气升之太过,或降之不及,以致气逆于上的一种病理变化。气逆,多因情志所伤,或饮食不当,或外邪侵犯,或痰浊壅阻所致,亦可因虚而无力下降导致气机上逆者。气逆多见于肺、肝、胃等脏腑。"},{"id":"2018-U0-012","unit":0,"number":12,"type":"A1/A2","stem":"气不能内守而大量亡失,以致生命机能突然衰竭的病理变化,指的是","options":{"A":"气虚","B":"气逆","C":"气陷","D":"气闭","E":"气脱"},"answer":"E","explanation":"气脱:指气虚至极,不能内守而大量脱失,以致生命机能突然衰竭的一种病理变化,多是由于正不敌邪,或慢性疾病长期耗气而衰竭,以致突然气不内守而外脱:或因大出血、大出汗等气随血脱或气随津泄而致气脱。"},{"id":"2018-U0-013","unit":0,"number":13,"type":"A1/A2","stem":"下列各项,适用于真寒假热证的治法是","options":{"A":"以热治寒","B":"以热治热","C":"以寒治寒","D":"用寒远寒","E":"通因通用"},"answer":"B","explanation":"热因热用,即以热治热,是用热性药物来治疗具有假热征象的病证。适用于阴盛格阳的真寒假热证。"},{"id":"2018-U0-014","unit":0,"number":14,"type":"A1/A2","stem":"属于中医诊断基本原理的是","options":{"A":"见微知著","B":"四诊合参","C":"辨证论治","D":"整体观念","E":"天人合一"},"answer":"A","explanation":"中医诊断的基本原理是建立在整体观念、相互联系认识基础之上的。具体有如下三点:司外揣内、见微知著、以常衡变。"},{"id":"2018-U0-015","unit":0,"number":15,"type":"A1/A2","stem":"蜷卧缩足,喜加衣被的临床意义是","options":{"A":"虚寒证","B":"实热证","C":"虚热证","D":"血虚证","E":"气虚证"},"answer":"A","explanation":"蜷卧缩足,喜加衣被者,多为虚寒证。仰卧伸足,掀去衣被,多属实热证。"},{"id":"2018-U0-016","unit":0,"number":16,"type":"A1/A2","stem":"揩舌主要判断的是","options":{"A":"是否属于染苔","B":"是否光线影响","C":"是否里有实邪","D":"是否舌质润泽","E":"是否运动灵活"},"answer":"A","explanation":"揩舌可用消毒纱布卷在食指上,蘸少许清洁水在舌面上揩抹数次。可用于鉴别舌苔有根无根,以及是否属于染苔。"},{"id":"2018-U0-017","unit":0,"number":17,"type":"A1/A2","stem":"黄滑苔的临床意义是","options":{"A":"湿热痰热内蕴,食积化腐","B":"阳虚寒湿内盛,痰饮内停","C":"阳虚寒湿之体,痰饮化热","D":"素有湿浊宿食,阻滞气机","E":"气血亏虚之体,痰饮食积"},"answer":"C","explanation":"苔淡黄而滑润多津(黄滑苔)多是阳虚寒湿之体,痰饮聚久化热,或为气血亏虚,复感湿热之邪。"},{"id":"2018-U0-018","unit":0,"number":18,"type":"A1/A2","stem":"神识清楚而语言错乱,语后自知言错的临床意义是","options":{"A":"心气不足","B":"邪热扰神","C":"脏气衰竭","D":"热入营血","E":"厥阴受寒"},"answer":"A","explanation":"错语指病人神识清楚而语言时有错乱,语后自知言错的症状。证有虚实之分,虚证多因心气虚弱,神气不足所致,多见于久病体虚或老年脏气衰微之人:实证多为痰湿、瘀血、气滞阻碍心窍所致。"},{"id":"2018-U0-019","unit":0,"number":19,"type":"A1/A2","stem":"突发耳鸣,声大如潮,按之不减的临床意义是","options":{"A":"寒水上泛","B":"肝胆郁热","C":"湿热蕴牌","D":"风邪上袭","E":"痰湿上蒙"},"answer":"D","explanation":"突发耳鸣,声大如雷,按之鸣声不减,或新病暴聋者,多属实证。可因肝胆火盛、肝阳上亢、痰火壅结、气血瘀阻、风邪上袭,或药毒损伤耳窍等所致。"},{"id":"2018-U0-020","unit":0,"number":20,"type":"A1/A2","stem":"肛门有下坠感,劳累后加重的临床意义是","options":{"A":"肝郁气滞","B":"大肠湿热","C":"肾气不固","D":"中气下陷","E":"肠道气滞"},"answer":"D","explanation":"肛门重坠指肛门有下坠之感的症状,常于劳累或排便后加重,多属脾虚中气下陷,常见于久泻或久痢不愈的患者。"},{"id":"2018-U0-021","unit":0,"number":21,"type":"A1/A2","stem":"洪脉、实脉的共同特征是","options":{"A":"来盛去衰","B":"如波涛汹涌","C":"部位表浅","D":"脉体宽大","E":"端直以长"},"answer":"D","explanation":"洪脉脉体宽大,充实有力,来盛去衰,状若波涛汹涌。其脉象特征主要表现在脉搏显现的部位、形态和气势三个方面。脉体宽大,搏动部位浅表,指下有力。实脉三部脉充实有力,其势来去皆盛,亦为有力脉象的总称。其脉象特征是脉搏搏动力量强,寸、关、尺三部,浮、中、沉三候均有力量,脉体宽大。因此答案选D。"},{"id":"2018-U0-022","unit":0,"number":22,"type":"A1/A2","stem":"平脉的脉动至数是","options":{"A":"一息五至","B":"一息四至","C":"一息六七至","D":"一息八九至","E":"一息十至"},"answer":"B","explanation":"平缓脉脉来和缓,一息四至(每分钟60~71次),应指均匀,是脉有胃气的一种表现,多见于正常人。"},{"id":"2018-U0-023","unit":0,"number":23,"type":"A1/A2","stem":"下列各项,属实证的临床表现是","options":{"A":"疼痛喜按","B":"五心烦热","C":"蒸蒸壮热","D":"精神萎靡","E":"舌胖淡嫩"},"answer":"C","explanation":"实证指人体感受外邪,或疾病过程中阴阳气血失调,体内病理产物蓄积,以邪气盛、正气不虚为基本病理,表现为有余、亢盛、停聚特征的各种证候。如蒸蒸壮热。"},{"id":"2018-U0-024","unit":0,"number":24,"type":"A1/A2","stem":"下列各项,属于证临床表现的是","options":{"A":"形体肥胖,皮下多触及圆滑柔韧的包块,舌苔白腻脉滑","B":"胸闷脘痞,呕吐清水,呕吐清稀痰涎","C":"眼睑、颜面先肿,迅速遍及全身,小便短少,咽喉肿痛","D":"下肢先肿,渐至全身,腹大痞胀,小便不利","E":"身体困重,肢体酸痛,腹胀腹泻,纳呆"},"answer":"A","explanation":"证是对疾病当前阶段的病位、病性等所作的结论,是机体在疾病发展过程中的某一阶段的病理概括,包括病变的部位、原因、性质,以及邪正关系。A项属于证临床表现。症状是病人主观的异常感觉或某些病态改变,BCDE四项都属于症状。"},{"id":"2018-U0-025","unit":0,"number":25,"type":"A1/A2","stem":"鉴别肝阳上亢证与肝火炽盛证最有意义的临床表现是","options":{"A":"口苦口干","B":"急躁易怒","C":"头重脚轻","D":"面红耳赤","E":"头晕胀痛"},"answer":"C","explanation":"肝火炽盛证、肝阳亢证的共同表现:头晕胀痛,面红目赤,口苦口干,急躁易怒,耳鸣,失眠。肝火炽盛证属火热过盛的实证,以目赤头痛、胁肋灼痛、苦口渴、便秘尿黄等火热症为主,阴虚证候不突出。肝阳上亢证属上实下虚,虚实夹杂,系肝肾阴虚阳亢所致,以眩晕、头目胀痛、头重脚轻等上亢症状为主,且见腰膝酸软、耳鸣等下虚症状,阴虚证候明"},{"id":"2018-U0-026","unit":0,"number":26,"type":"A1/A2","stem":"久病咳喘,呼多吸少的临床意义是","options":{"A":"肺气虚","B":"心肺气虚","C":"肾不纳气","D":"脾肺气虚","E":"肺气阴两虚"},"answer":"C","explanation":"肺肾气虚证是指肺肾气虚,摄纳无权,以久病咳喘、呼多吸少、动则尤甚等为主要表现的虚弱证候,又名肾不纳气证。"},{"id":"2018-U0-027","unit":0,"number":27,"type":"A1/A2","stem":"伤寒论中,小柴胡汤证的临床表现是","options":{"A":"往来寒热,胸胁苦满,嘿嘿不欲饮食,心烦喜呕","B":"口苦咽干,寒热往来,胸胁苦满,脉弦","C":"胸烦满,烦惊谵语,小便不利,一身尽重","D":"心下痞硬,呕不止,郁郁微烦","E":"潮热汗出,腹满痛,狂躁谵语,不得眠"},"answer":"A","explanation":"《伤寒论》:“伤寒五六日,中风,往来寒热,胸胁苦满,嘿嘿不欲饮食,心烦喜呕,或胸中烦而不呕,或渴,或腹中痛,或胁下痞硬,或心下悸,小便不利,或不渴,身有微热,或咳者,小柴胡汤主之。"},{"id":"2018-U0-028","unit":0,"number":28,"type":"A1/A2","stem":"下列各项,不属温热药的作用的是","options":{"A":"温里散寒","B":"滋阴除蒸","C":"暖肝散结","D":"引火归元","E":"回阳救逆"},"answer":"B","explanation":"温热药分别具有温里散寒、暖肝散结、补火助阳、温阳利水、温经通络、引火归元、回阳救逆等作用。"},{"id":"2018-U0-029","unit":0,"number":29,"type":"A1/A2","stem":"荆芥与蝉蜕的共同功效是","options":{"A":"透疹","B":"解毒","C":"消疮","D":"止血","E":"平肝"},"answer":"A","explanation":"荆芥:祛风解表、透疹消疮,炭炒止血。蝉蜕:疏散风热、利咽透疹开音、明目退翳、息风止痉。故二者均能透疹。"},{"id":"2018-U0-030","unit":0,"number":30,"type":"A1/A2","stem":"患者咳嗽,干咳无痰,颧红,盗汗,午后及夜间低热,治疗方中不应出现的药物是","options":{"A":"知母","B":"麦冬","C":"鳖甲","D":"地骨皮","E":"石膏"},"answer":"E","explanation":"患者咳嗽,干咳无痰,颧红,盗汗,午后及夜间低热,其病机为阴虚。石膏使用注意:脾胃虚寒及阴虚内热者忌用。ABCD四项属于清虚热药,可以使用。"},{"id":"2018-U0-031","unit":0,"number":31,"type":"A1/A2","stem":"连翘用治热淋涩痛的机理是","options":{"A":"凉血止血","B":"渗湿止痛","C":"利湿去浊","D":"收涩止痛","E":"清心利尿"},"answer":"E","explanation":"连翘功效:清热解毒,消肿散结,疏散风热。其苦寒通降,兼有清心利尿之功,多与车前子、白茅根、竹叶等药配伍,治疗湿热壅滞所致小便不利或淋沥涩痛,如如圣散。"},{"id":"2018-U0-032","unit":0,"number":32,"type":"A1/A2","stem":"甘遂与大戟的共同功效是","options":{"A":"泻水逐饮","B":"去积杀虫","C":"峻下冷积","D":"活血化瘀","E":"润燥软坚"},"answer":"A","explanation":"甘遂功效:泻水逐饮,消肿散结。,京大戟功效:泻水逐饮消肿散结。"},{"id":"2018-U0-033","unit":0,"number":33,"type":"A1/A2","stem":"具有燥湿,健脾功效的药组是","options":{"A":"山药,大枣","B":"苍术,白术","C":"盐香,佩兰","D":"砂仁,草果","E":"厚朴,茯苓"},"answer":"B","explanation":"苍术功效:燥湿健脾,祛风散寒,明目。白术功效:健脾益气,燥湿利水,止汗,安胎。"},{"id":"2018-U0-034","unit":0,"number":34,"type":"A1/A2","stem":"性寒,可用治淋证","options":{"A":"薏苡仁","B":"海金沙","C":"车前子","D":"瞿麦","E":"石韦"},"answer":"C","explanation":"车前子性能:甘,寒。归肝、肾、肺、小肠经。功效:清热利尿通淋,渗湿止泻,明目,祛痰。"},{"id":"2018-U0-035","unit":0,"number":35,"type":"A1/A2","stem":"常与党参,白术配伍,用治脾胃虚寒腹痛的药物是","options":{"A":"干姜","B":"附子","C":"肉桂","D":"生姜","E":"吴茱萸"},"answer":"A","explanation":"干姜功效:温中散寒,回阳通脉,温肺化饮。干姜辛热燥烈,主入脾胃而长于温中散寒、健运脾阳,为温暖中焦之主药。多与党参、白术等同用,治脾胃虚寒,脘腹冷痛等。"},{"id":"2018-U0-036","unit":0,"number":36,"type":"A1/A2","stem":"治疗饮食积滞,泻痢腹痛,首选药物是","options":{"A":"莱菔子","B":"麦芽","C":"神曲","D":"山楂","E":"鸡内金"},"answer":"D","explanation":"山楂功效:消食健胃,行气散瘀,化浊降脂。山楂入肝经,能行气散结止痛,炒用兼能止泻止痢。"},{"id":"2018-U0-037","unit":0,"number":37,"type":"A1/A2","stem":"不具有杀虫消积功效的药物是","options":{"A":"使君子","B":"苦楝皮","C":"槟榔","D":"雷丸","E":"榧子"},"answer":"B","explanation":"苦楝皮功效:杀虫,疗癣。主治病证:蛔虫病,蛲虫病,钩虫病;疥癣,湿疮。苦楝皮并无消积的功效。"},{"id":"2018-U0-038","unit":0,"number":38,"type":"A1/A2","stem":"益母草治的病症是","options":{"A":"痰瘀互阻水肿","B":"脾肾阳虚水肿","C":"水瘀互阻水肿","D":"寒湿下注水肿","E":"风水水肿"},"answer":"C","explanation":"益母草功效:活血调经,利尿消肿,清热解毒。既能利水消肿,又能活血化瘀,尤宜用于水瘀互阻的水肿。"},{"id":"2018-U0-039","unit":0,"number":39,"type":"A1/A2","stem":"性平,可治疗经闭,腰膝酸痛,淋证的药物是","options":{"A":"牛膝","B":"桃仁","C":"川芎","D":"益母草","E":"鸡血藤"},"answer":"A","explanation":"牛膝性能:苦、甘、酸、平。归肝、肾经。功效:逐瘀通经,补肝肾,强筋骨,利水通淋,引火(血)下行。主治:.瘀血阻滞的经闭、痛经、经行腹痛、胞衣不下、跌打伤痛。@腰膝酸痛,下肢痿软。@淋证,水肿,小便不利。@上部火热证"},{"id":"2018-U0-040","unit":0,"number":40,"type":"A1/A2","stem":"具有活血,凉血功效的药组是","options":{"A":"延胡索,姜黄","B":"土鳖虫,乳香","C":"郁金,丹参","D":"姜黄,红花","E":"水蛭,莪术"},"answer":"C","explanation":"郁金功效:活血止痛,行气解郁,清心凉血,利胆退黄。丹参功效:活血祛瘀,通经止痛,清心除烦,凉血消痈。"},{"id":"2018-U0-041","unit":0,"number":41,"type":"A1/A2","stem":"桔梗治疗咳嗽痰多,其机理是","options":{"A":"降气消痰","B":"燥湿祛痰","C":"清肺化痰","D":"宣肺祛痰","E":"泻肺化痰"},"answer":"D","explanation":"桔梗功效:宣肺,祛痰,利咽,排脓。其辛散苦泄,专入肺经,化痰并能开宣肺气。因其性平,故咳嗽无论属寒、属热,有痰、无痰均可应用。属寒者常配紫苏、杏仁,如杏苏散:属热者,常配桑叶、菊花,如桑菊饮:痰多者,宜配化痰药。"},{"id":"2018-U0-042","unit":0,"number":42,"type":"A1/A2","stem":"半夏与天南星的共同主治是","options":{"A":"湿痰","B":"便秘","C":"呕吐","D":"吐血","E":"中风"},"answer":"A","explanation":"半夏与天南星,二药均辛温有毒,均能燥湿化痰、温化寒痰,主治湿痰、寒痰证,炮制后又能治疗热痰、风痰:外用均能消肿止痛,用治疮疡肿毒以及毒蛇咬伤。"},{"id":"2018-U0-043","unit":0,"number":43,"type":"A1/A2","stem":"泻肺中水饮及痰火而平喘咳的药物是","options":{"A":"旋覆花","B":"瓜蒌","C":"紫菀","D":"枇杷叶","E":"葶苈子"},"answer":"E","explanation":"葶苈子功效:泻肺平喘,行水消肿。本品苦降辛散,性寒清热,专泻肺中水饮及痰火而平喘咳。常佐大枣以缓其性,如葶苈大枣泻肺汤。"},{"id":"2018-U0-044","unit":0,"number":44,"type":"A1/A2","stem":"患者露天睡觉后出现脘腹疼痛,呕吐,肠鸣腹泻,苔白润,脉弦紧,其辨证是","options":{"A":"风淫证","B":"伤寒证","C":"湿淫证","D":"暑淫证","E":"中寒证"},"answer":"E","explanation":"中寒证是指寒邪直接内侵脏腑、气血,遏制及损伤阳气,阻滞脏腑气机和血液运行所表现的里实寒证,又称内寒证、里寒证等。寒邪客于不同脏腑,可有不同的证候特点,寒邪客肺,肺失宣降,故见咳嗽、哮喘、咯稀白痰等症;寒滞胃肠,使胃肠气机失常,运化不利,则见脘腹疼痛、肠鸣腹泻、呕吐等症。"},{"id":"2018-U0-045","unit":0,"number":45,"type":"A1/A2","stem":"患者咳嗽,少痰难咯,微有发热恶寒,其辨证是","options":{"A":"风热犯肺证","B":"风寒束肺证","C":"肺阴亏虚证","D":"燥邪犯肺证","E":"肺热炽盛证"},"answer":"D","explanation":"燥邪犯肺证是指外感燥邪,肺失宣降,以干咳痰少、鼻咽口舌干燥等为主要表现的证候,简称肺燥证。临床表现:干咳无痰,或痰少而黏、不易咯出,甚则胸痛,痰中带血,或见鼻衄,囗、唇、鼻《咽、皮肤干燥,尿少,大便干结,舌苔薄而干燥少津。或微有发热恶风寒,无汗或少汗脉浮数或浮紧。"},{"id":"2018-U0-046","unit":0,"number":46,"type":"A1/A2","stem":"患者发热囗渴,小便灼热涩痛,小腹胀痛,舌红苔黄腻,脉数,其辨证是","options":{"A":"小肠实热证真20/8","B":"膀胱湿热证","C":"湿热蕴脾证","D":"肝胆湿热证","E":"肠道湿热证"},"answer":"B","explanation":"膀胱湿热证是指湿热侵袭,蕴结膀胱,一以小便频急、灼涩疼痛及湿热症状为主要表现的证候。临床表现:小便频数,排尿灼热涩痛,小便短赤,尿血或有砂石,小腹胀痛,腰痛,发热口渴,舌红苔黄腻,脉濡数。"},{"id":"2018-U0-047","unit":0,"number":47,"type":"A1/A2","stem":"温热病,低热日久,持续不退,暮热早凉,五心烦热,干咽燥,神倦形瘦,舌绛,脉细数。宜选用的方剂是","options":{"A":"黄连阿胶汤","B":"大定风珠","C":"加减复脉汤","D":"三甲复脉汤","E":"清营汤"},"answer":"C","explanation":"本证属于春温后期,邪热深入下焦余邪久羁,耗伤肝肾真阴而致,属邪少虚多之候。阴虚不能制阳,则阳偏亢而低热不己。口干咽燥是肾阴亏损,津难上乘之象。阴精亏损较甚,神失所养,则可见神倦形瘦等表现。舌绛,为肝血肾液耗伤之证。阴虚则脉细数。应予加减复脉汤滋阴养液。"},{"id":"2018-U0-048","unit":0,"number":48,"type":"A1/A2","stem":"下列各项,属于消法适应证的是","options":{"A":"脓液黄稠的溃疡","B":"疮疡溃后","C":"未化脓的初期肿疡","D":"化脓性肿块","E":"疮疡内陷"},"answer":"C","explanation":"消法是运用不同治疗方法和方药,使初起肿疡得到消散,是一切肿疡初起的治法总则。适用于尚未成脓的初期肿疡和非化脓性肿块性疾病及各种皮肤性疾病。"},{"id":"2018-U0-049","unit":0,"number":49,"type":"A1/A2","stem":"下列关于切开法的切囗选择,正确的是","options":{"A":"手指脓肿宜在指膜切开","B":"关节脓肿应广泛越关节切开","C":"头面部脓肿应纵形切开","D":"乳房脓肿以乳头为中心放射状切开","E":"肛周脓肿应纵形切开"},"answer":"D","explanation":"一般疮疡宜循经直切:乳房部应以乳头为中心,放射状切开:面部脓肿应尽量沿皮肤自然纹理切开;手指脓肿,应从侧方切开;关节区附近的脓肿,切囗尽量避免越过关节:关节区脓肿,一般施行横切口、弧形切口或“S”形切口;肛旁低位脓肿,应以肛管为中心作放射状切开。"},{"id":"2018-U0-050","unit":0,"number":50,"type":"A1/A2","stem":"治疗颈痈风热痰毒证,应首选的方剂是","options":{"A":"仙方活命饮","B":"黄连解毒汤","C":"五味消毒饮","D":"牛蒡解肌汤","E":"五神汤"},"answer":"D","explanation":"颈痈风热痰毒证治法:散风清热,化痰消肿。方药:牛蒡解肌汤或银翘散加减。"},{"id":"2018-U0-051","unit":0,"number":51,"type":"A1/A2","stem":"下列关于蛇串疮的叙述,正确的是","options":{"A":"皮损对称分布","B":"多无疼痛","C":"皮损为红斑,风团","D":"愈后很少复发","E":"相当于西医的单纯疱疹"},"answer":"D","explanation":"以解析〗蛇串疮是一种皮肤上出现成簇水疱,多呈带状分布,痛如火燎的急性疱疹性皮肤病。相当于西医的带状疱疹。特点为皮肤上出现红斑、水疱或丘疱疹,累累如串珠,排列成带状,沿一侧周围神经分布区出现,局部刺痛或伴臀核肿大。多数患者愈后很少复发,极少数患者可多次发病。秃到秃头"},{"id":"2018-U0-052","unit":0,"number":52,"type":"A1/A2","stem":"疥疮的治疗原则是","options":{"A":"清热解毒","B":"清热燥湿","C":"祛风止痒","D":"燥湿解毒","E":"杀毒止痒"},"answer":"E","explanation":"疥疮以杀虫止痒为主要治法。必须隔离治疗,以外治为主。般不需内服药,若抓破染毒,需内外合治。"},{"id":"2018-U0-053","unit":0,"number":53,"type":"A1/A2","stem":"内痔脱出不能自行还纳,需手托,休息方能复位,其分期","options":{"A":"I期","B":"II期","C":"III期","D":"IV期","E":"V期"},"answer":"C","explanation":"I期内痔:痔核较小,不脱出,以便血为主。II期内痔:痔核较大,大便时可脱出肛外,便后自行回纳,便血或多或少。III期内痔:痔核更大,大便时痔核脱出肛外,甚至行走、咳嗽、喷嚏、站立时也会脱出,不能自行回纳,须用手推回,或平卧、热敷后才能回纳,便血不多或不出血。IV期内痔:痔核脱出,不能及时回纳,嵌顿于外,因充血、水肿和血栓形成,以致肿痛、糜烂和坏死,即嵌顿性内痔。5生"},{"id":"2018-U0-054","unit":0,"number":54,"type":"A1/A2","stem":"女性生殖器官中,防御外邪入侵的第一道门户是","options":{"A":"子门","B":"阴道","C":"子宫","D":"玉门","E":"阴户"},"answer":"E","explanation":"阴户是防御外邪入侵的第一道门户,是排月经、泌带下、排恶露之出口,是合阴阳之入口,又是娩出胎丿L、胎盘之产门。"},{"id":"2018-U0-055","unit":0,"number":55,"type":"A1/A2","stem":"下列关于妊娠期子宫的叙述,错误的是","options":{"A":"子宫颈紫蓝色,质软","B":"妊娠足月子宫容量约5000m1","C":"早孕40多天,可扪及子宫增大变软","D":"妊娠足月子宫较正常子宫容量增加100倍","E":"妊娠足月子宫较正常子宫重量增加20倍"},"answer":"D","explanation":"子宫增大是妊娠生理之一。孕后子宫育胎,变化最大。早孕40多天,可扪及子宫增大变软,子宫颈紫蓝色质软。非孕时子宫容量为5ml,至妊娠足月约5000m].,增加1000倍。子宫重量,非孕时50g,至足月妊娠约1000g,增加20倍。"},{"id":"2018-U0-056","unit":0,"number":56,"type":"A1/A2","stem":"与妇科疾病关系最为密切的脏腑是","options":{"A":"肾、肝、心","B":"肾、肝、脾","C":"肾、肝、肺","D":"肾、心、脾","E":"肾、肺、脾"},"answer":"B","explanation":"人体是以五脏为中心的有机整体,脏腑生理功能的紊乱和脏腑气血阴阳的失调,均可导致妇产科疾病,其中关系最密切的是肾、肝、脾三脏。"},{"id":"2018-U0-057","unit":0,"number":57,"type":"A1/A2","stem":"中医妇科治法中,滋肾益阴的代表方剂是","options":{"A":"左归丸","B":"寿胎丸","C":"归肾丸","D":"大补元煎","E":"补肾固冲丸"},"answer":"A","explanation":"肾阴不足,治宜滋肾益阴。常用地黄、枸杞子、黄精、女贞子过旱莲草、制首乌、菟丝子、桑葚子等。方如左归丸、补肾地黄汤、六味地黄丸。"},{"id":"2018-U0-058","unit":0,"number":58,"type":"A1/A2","stem":"闭经的治疗原则是","options":{"A":"补而通之,泻而通之","B":"理气活血,祛瘀通经","C":"益气养血,以益冲任","D":"补益肝肾,以填精血","E":"补中有通,补而不腻"},"answer":"A","explanation":"闭经的治疗原则应根据病证,虚者补而通之,实者泻而通之。通过补益之法,使气血恢复,脏腑平衡《血海充盛,一则经自行。,若因病而致经闭,又当先治原发疾病,待病愈则经可复行;经仍未复潮者,再辨证治之。"},{"id":"2018-U0-059","unit":0,"number":59,"type":"A1/A2","stem":"带下过少肝肾亏损证的治法是","options":{"A":"滋补肝肾,养精益血","B":"滋阴补肾,调补冲任","C":"滋肾养肝,补血益气","D":"滋阴补肾,补益气血","E":"滋阴养肝,疏肝理气"},"answer":"A","explanation":"带下过少肝肾亏损证治法:滋补肝肾养精益血。方药:左归丸加知母、肉苁蓉、紫河车、麦冬。"},{"id":"2018-U0-060","unit":0,"number":60,"type":"A1/A2","stem":"按照公式计算,3岁小儿的标准身高、体重分别是","options":{"A":"12kg,91cm","B":"12kg,98cm","C":"14kg,96cm","D":"14kg,98cm","E":"16kg,96cm"},"answer":"C","explanation":"新生儿出生时体重约为3kgo临床可以用以下公式推算小丿体重:2岁以上体重(kg):8+2×年龄。临床可用以下公式估算2岁后至12岁儿童的身高:身高(cm)=75+7×年龄。其体重(kg)=8+2×3=14:身高(cm)=75+7×3=96。"},{"id":"2018-U0-061","unit":0,"number":61,"type":"A1/A2","stem":"邪热郁滞的指纹色是","options":{"A":"深紫","B":"紫红","C":"青紫","D":"淡红","E":"鲜红浮露"},"answer":"B","explanation":"纹色鲜红浮露,多为外感风寒;纹色紫红,多为邪热郁滞:纹色淡红,多为内有虚寒:纹青紫,多为瘀热内结:纹色深紫,多为瘀滞络闭,病情深重。"},{"id":"2018-U0-062","unit":0,"number":62,"type":"A1/A2","stem":"小儿遗尿的中医治疗原则是","options":{"A":"温补肾阳,滋补肾阴","B":"滋阴潜阳,补益肾气","C":"补益肾气,利尿通淋","D":"温补下元,固摄膀胱","E":"补益脾肾,益气温阳"},"answer":"D","explanation":"遗尿以温补下元、固摄膀胱为主要治疗原则,采用温肾阳、益脾气、补肺气、醒心神、固膀胱等法,偶需泻肝清热。"},{"id":"2018-U0-063","unit":0,"number":63,"type":"A1/A2","stem":"小丿L水痘的皮疹特征是","options":{"A":"丘疹,疱疹,结痂同时存在","B":"疹退后糠麸样脱屑","C":"热退疹出","D":"疹退后无脱皮","E":"疹退后留瘢痕"},"answer":"A","explanation":"水痘是由水痘时邪引起的一种传染性强的出疹性疾病。以发热,皮肤黏膜分批出现瘙痒性皮疹,丘疹、疱疹、结痂同时存在为主要特征。"},{"id":"2018-U0-064","unit":0,"number":64,"type":"A1/A2","stem":"治疗维生素D缺乏性佝偻病肾精亏损证,首选的方剂是","options":{"A":"左归丸","B":"右归丸","C":"金匮肾气丸","D":"补肾地黄丸","E":"十全大补汤"},"answer":"D","explanation":"维生素D缺乏性佝偻病肾精亏损证治法:补肾填精,佐以健脾。代表方剂:补肾地黄丸。"},{"id":"2018-U0-065","unit":0,"number":65,"type":"A1/A2","stem":"COPD最主要的病因是","options":{"A":"吸烟","B":"环境污染","C":"感染","D":"寒冷气候","E":"过敏原因"},"answer":"A","explanation":"吸烟为COPD最主要的病因,发病与吸烟的时间长短、吸烟量、吸烟的种类等有一定的关系。"},{"id":"2018-U0-066","unit":0,"number":66,"type":"A1/A2","stem":"慢性左心衰竭最早出现的临床表现是","options":{"A":"咳粉红色泡沫样痰","B":"心悸、胸闷","C":"劳力性呼吸困难","D":"尿量减少","E":"下肢水肿"},"answer":"C","explanation":"左心衰竭以肺淤血及心排血量降低的表现为主,症状多明显,但体征不具特征性。劳力性呼吸困难是最早出现的临床表现,呼吸困难发生在重体力活动时,休息后可缓解。"},{"id":"2018-U0-067","unit":0,"number":67,"type":"A1/A2","stem":"急性心肌梗死溶栓治疗后判定冠脉再通常用的实验室检查是","options":{"A":"肌钙蛋白","B":"门冬氨酸氨基转移酶","C":"乳酸脱氢酶","D":"CK—MB","E":"C反应蛋白"},"answer":"D","explanation":"冠脉再通的判断:.心电图抬高的ST段于2小时内回降超过50%;@胸痛2小时内基本消失:02小时内出现再灌注性心律失常:@血清CKMB酶峰值提前出现(14小时内)。"},{"id":"2018-U0-068","unit":0,"number":68,"type":"A1/A2","stem":"胃溃疡的主要症状是","options":{"A":"反酸,嗳气","B":"进食后上腹饱胀","C":"上腹部疼痛","D":"恶心不伴呕吐","E":"食欲不振"},"answer":"C","explanation":"消化性溃疡的典型表现为慢性、周期性、节律性的上腹部疼痛,体征多不典型。"},{"id":"2018-U0-069","unit":0,"number":69,"type":"A1/A2","stem":"鉴别原发性甲亢与继发性甲亢的敏感指标是","options":{"A":"TT3、TT4","B":"FT3、FT4","C":"TSH","D":"甲状腺摄13H率","E":"甲状腺超声改变"},"answer":"C","explanation":"TSH测定是反映甲状腺功能最敏感的指标,也是反映下丘脑一垂体一甲状腺轴功能、鉴别原发性与继发性甲亢的敏感指标,尤其对亚临床型甲亢和甲减的诊断具有更重要意义。"},{"id":"2018-U0-070","unit":0,"number":70,"type":"A1/A2","stem":"尿路感染最常见的致病菌是","options":{"A":"变形杆菌","B":"金黄色葡萄球菌","C":"克雷伯杆菌","D":"大肠埃希菌","E":"铜绿假单胞菌"},"answer":"D","explanation":"尿路感染是指各种病原微生物引起的尿路感染性疾病,其中以细菌感染最为多见。最常见的致病菌为革兰阴性杆菌,其中以大肠埃希菌最常见,其次为变形杆菌、克雷伯杆菌。"},{"id":"2018-U0-071","unit":0,"number":71,"type":"A1/A2","stem":"下列各项,符合流脑","options":{"A":"外观浑浊呈脓性,细胞数明显减少,氯化物降低,蛋白增高,糖降低","B":"外观浑浊呈脓性,细胞数明显升高,氯化物降低,蛋白降低,糖升高","C":"外观浑浊呈脓性,细胞数明显升高,氯化物降低,蛋白增高,糖降低","D":"外观浑浊呈脓性,细胞数稍多,氯化物正常,蛋白轻度增高,糖正常","E":"外观浑浊,细胞数明显减少,氯化物降低,蛋白增高,糖"},"answer":"C","explanation":"脑脊液检查是明确流脑诊断的重要方法,初起或休克型患者脑脊液多无改变。其他型可见脑脊液可呈脓性,压力升高,外观混浊,白细胞明显增高,蛋白质增高,而糖及氯化物明显降低。但流脑初期或经抗菌药物治疗口脑脊液改变可以不典型。"},{"id":"2018-U0-072","unit":0,"number":72,"type":"A1/A2","stem":"下列关于伤寒的叙述,错误的是","options":{"A":"由伤寒杆菌引起的急性传染病","B":"传染源为患者和带菌者","C":"传播途径为粪一口途径","D":"夏秋季节高发","E":"慢性带菌者传染性最强"},"answer":"E","explanation":"患者和带菌者是伤寒的唯一传染源。患者自潜伏期开始即从粪便中排菌,发病后2、4周排菌量最多,传染性最强。少数患者病后可成为长期带菌者,持续带菌超过3个月一者称为慢性带菌者。"},{"id":"2018-U0-073","unit":0,"number":73,"type":"A1/A2","stem":"隐性感染病例增加的临床生理意义是","options":{"A":"典型病例增加","B":"轻症病例增加","C":"潜在感染病例增加","D":"病原携带病例增加","E":"免疫人群增加"},"answer":"E","explanation":"传染病流行或隐性感染后免疫人群增加,在传染病流行后的一段时间内,人群对该病易感性降低。"},{"id":"2018-U0-074","unit":0,"number":74,"type":"A1/A2","stem":"患者,男,65岁,咳喘20年,动则喘甚,呼多吸少,气不得续,形瘦神疲,汗出肢冷,面青唇紫,舌淡苔白,脉微细,治疗应首选的方剂是","options":{"A":"济生肾气丸合生脉散","B":"七味都气丸合参附汤","C":"金匮肾气丸合参蛤散","D":"参附汤合黑锡丹","E":"苏子降气汤合四逆汤"},"answer":"C","explanation":"根据患者的临床表现诊断为喘证肾虚不纳证。其证候:喘促日久,动则喘甚,呼多吸少,气不得续,形瘦神惫,跗肿,汗出肢冷,面青唇紫,舌淡苔白或黑而润滑,脉微细或沉弱:或见喘咳,面红烦躁,口咽干燥,足冷,汗出如油,舌红少津,脉细数。治法:补肾纳气。代表方:金匮肾气丸合参蛤散加减。"},{"id":"2018-U0-075","unit":0,"number":75,"type":"A1/A2","stem":"五患者,女,69岁,左胸部闷痛4年,近来胸闷频发,痰多气短,肢体沉重,形体肥胖,偶有心悸眩晕,纳呆便溏,咯吐痰涎,舌体胖大边有齿痕,苔白腻,脉滑,其辨证是","options":{"A":"气滞心胸证","B":"寒凝心脉证","C":"痰浊闭阻证","D":"心肾阳虚证","E":"阴虚火旺证"},"answer":"C","explanation":"根据患者的临床症状诊断为胸痹痰浊闭阻证。其证候:胸闷重而心痛微,痰多气短,肢体沉重,形体肥胖,遇阴雨天而易发作或加重,伴有心悸眩晕,纳呆便溏,咯吐痰涎,舌体胖大且边有齿痕,苔浊腻或白滑,脉滑。秃到秃头"},{"id":"2018-U0-076","unit":0,"number":76,"type":"A1/A2","stem":"患者,女,40岁,全身水肿3年,下肢明显,小便短少,身体困重,胸闷,纳呆,舌质淡,苔白腻,脉沉缓,其治法","options":{"A":"宜肺解毒,利湿消肿","B":"运脾化湿,通阳利水","C":"健脾行气,利水消肿","D":"温肾助阳,化气行水","E":"活血祛瘀,化气行水"},"answer":"B","explanation":"根据患者的临床表现诊断为水肿水湿浸渍证。证候:起病缓慢,病程较长,全身水肿,下肢明显,按之没指,小便短少,身体困重,胸闷,纳呆,泛恶,苔白腻,脉沉缓。治法:运脾化湿,通阳利水。代表方:五皮饮合胃苓汤加减。"},{"id":"2018-U0-077","unit":0,"number":77,"type":"A1/A2","stem":"患者,女,38岁,心悸6年,善惊易恐,坐卧不安,多梦易醒,舌苔薄白,脉虚数。其辨证是","options":{"A":"心阴亏虚证","B":"阴虚火旺证","C":"心虚胆怯证","D":"血脉瘀阻证","E":"水引凌心证"},"answer":"C","explanation":"根据患者的临床表现诊断为心虚胆怯证。其证候:心悸不宁,善惊易恐,坐卧不安,不寐多梦而易惊醒,恶闻声响,食少纳呆,苔薄白,脉细略数或细弦。治法:镇惊定志,养心安神。代表方:安神定志丸加减。"},{"id":"2018-U0-078","unit":0,"number":78,"type":"A1/A2","stem":"患者,男,32岁,心胸疼痛,痛处拒按,如刺如绞,入夜尤甚,脉象沉涩,治疗应首选的方剂是","options":{"A":"血府逐瘀汤","B":"龙胆泻肝汤","C":"一贯煎","D":"柴胡疏肝散","E":"黄芪建中汤"},"answer":"A","explanation":"根据患者的临床表现诊断为胸痹心血瘀阻证其证候:心胸疼痛,如刺如绞,痛有定处,.一入夜为甚,甚则心痛彻背,背痛彻心,或痛引肩背,伴有胸闷,日久不愈,可因暴怒、劳累而加重,,舌质紫暗,有瘀斑,苔薄,脉弦涩。治法:活血化瘀,通脉止痛。代表方:血府逐瘀汤加减。"},{"id":"2018-U0-079","unit":0,"number":79,"type":"A1/A2","stem":"患者,男,80岁,排便困难3年,大便艰涩,腹痛拘急,胀满拒按,胁下偏痛,手足不温,呃逆呕吐,舌苔白腻,脉弦紧,治疗应首选的方剂是","options":{"A":"济川煎","B":"黄芪汤","C":"补中益气汤","D":"温脾汤","E":"青麟丸"},"answer":"D","explanation":"根据患者的临床表现诊断为便秘冷秘。其证候:大便艰涩,腹痛拘急,胀满拒按,胁下偏痛,手足不温,呃逆呕吐,舌苔白腻,脉弦紧。治法:温里散寒,通便止痛。代表方:温脾汤加减。"},{"id":"2018-U0-080","unit":0,"number":80,"type":"A1/A2","stem":"患者,女,眩晕8年,眩晕日久不愈,精神萎靡,腰膝酸软,少寐多梦,健忘,两目干涩,视力减退,五心烦热,舌红少苔,脉细数,治疗应首选的方剂是","options":{"A":"右归丸","B":"左归丸","C":"附子理中汤","D":"七味都气丸","E":"金匮肾气丸"},"answer":"B","explanation":"根据患者的临床症状诊断为眩晕肾精不足证。证候:眩晕日久不愈,精神萎靡,腰酸膝软,少寐多梦,健忘,两目干涩,视力减退,或遗精滑泄,耳鸣齿摇。或颧红咽干,五心烦热,舌红少苔,脉细数;或面色恍白,形寒肢冷,舌淡嫩,苔白,脉弱尺甚。治法:滋养肝肾,益精填髓。代表方:左归丸加减。"},{"id":"2018-U0-081","unit":0,"number":81,"type":"A1/A2","stem":"患者,男,60岁,反复胃脘部疼痛10年,现症:胃脘疼痛,如针刺,痛有定数,按之痛苦,痛时持久,食后加剧,入夜尤甚,舌质紫黯,脉涩,治疗应首选的方剂是","options":{"A":"血府逐瘀汤","B":"桃仁红花煎","C":"膈下逐瘀汤","D":"失笑散合丹参饮","E":"桃红四物汤"},"answer":"D","explanation":"根据患者的临床表现诊断为胃痛瘀血停胃证。证候:胃脘疼痛,如针刺,似刀割,痛有定处,按之痛甚,痛时持久,食后加剧,入夜尤甚,或见吐血黑便,舌质紫暗或有瘀斑,脉涩。治法:化瘀通络,理气和胃。代表方:失笑散合丹参饮加减。"},{"id":"2018-U0-082","unit":0,"number":82,"type":"A1/A2","stem":"患者,女,65岁,诊断为“类风湿性关节炎”5年,四肢关节疼痛,固定不移,肌肤紫暗,关节僵硬变形,屈伸不利,胸闷痰多,舌质紫暗,苔白腻,脉弦涩,其治法是","options":{"A":"祛风通络,化痰除湿","B":"散寒通络,祛风除湿","C":"除湿通络,活血化瘀","D":"清热通络,祛风除湿","E":"化痰行瘀,蠲痹通络"},"answer":"E","explanation":"根据患者的临床表现诊断为痹症痰瘀痹阻证。证候:痹证日久,肌肉关节刺痛,固定不移,或关节肌肤紫暗、肿胀,按之较硬,肢体顽麻或重着,或关节僵硬变形,屈伸不利,有硬结、瘀斑,面色暗黧,眼睑浮肿,或胸闷痰多,舌质紫暗或有瘀斑,舌苔白腻,脉弦涩。治法:化痰行瘀,蠲痹通络。"},{"id":"2018-U0-083","unit":0,"number":83,"type":"A1/A2","stem":"患者,女,30岁,左颈部核桃大小卵圆形肿物,不红,不热,随吞咽上下移动,舌苔白腻,脉弦,治疗应首选的方剂是","options":{"A":"逍遥散合栝楼牛蒡汤","B":"逍遥散合海藻玉壶汤","C":"四海舒郁丸","D":"逍遥蒌贝散","E":"柴胡疏肝散合栝楼牛蒡汤"},"answer":"B","explanation":"根据患者的临床症状诊断为肉癭气滞痰凝证,其证候:颈部一侧或两侧肿块呈圆形或卵圆形,不红、不热,随吞咽动作上下移动;一般无明显全身症状,如肿块过大可有呼吸不畅或吞咽不利;苔薄腻,脉弦滑。治法:理气解郁,化痰软坚。方药:逍遥散合海藻玉壶汤加减。"},{"id":"2018-U0-084","unit":0,"number":84,"type":"A1/A2","stem":"患者,女,30岁,突发出现斑片脱发2天,偶有头皮瘙痒,伴头皮炽热,心烦易怒,急躁不安,舌质红,舌苔薄,脉弦,其辨证是","options":{"A":"气滞血瘀证","B":"湿热壅盛证","C":"肝肾不足证","D":"气血两虚证","E":"血热风燥证"},"answer":"E","explanation":"根据患者的临床症状诊断为油风血热风燥证,其证候:突然脱发成片,偶有头皮瘙痒,或伴头部烘热:心烦易怒,急躁不安;舌质红,舌苔薄,脉弦。治法:凉血息风,养阴护发。方药:四物汤合六味地黄汤加减。"},{"id":"2018-U0-085","unit":0,"number":85,"type":"A1/A2","stem":"患者,男30岁,不洁性交后3月,冠状沟出现数个菜花状丘疹,色淡红,质柔软,舌质红,苔薄白,脉弦,其诊断","options":{"A":"梅毒","B":"生殖器疱疹","C":"淋病","D":"尖锐湿疣","E":"艾滋病"},"answer":"D","explanation":"根据患者的临床表现诊断为尖锐湿疣。尖锐湿疣的诊断:临床表现有与尖锐湿疣患者不洁性交或生活接触史。外生殖器及肛门周围皮肤黏膜湿润区为好发部位,少数患者可见于肛门生殖器以外部位。基本损害为淡红色或污秽色、柔软的表皮赘生物。"},{"id":"2018-U0-086","unit":0,"number":86,"type":"A1/A2","stem":"患者,男,60岁,排便后肛门部肿物脱出反复发作3年,患者每次便时肿物脱出长5cm、10cm,色淡红,伴肛门坠胀,神疲乏力,食欲不振,舌质淡,苔薄白,脉细弱,其治法是","options":{"A":"清热利湿","B":"养阴润肠","C":"补气升提","D":"理气活血","E":"益气温阳"},"answer":"C","explanation":"根据患者的临床表现诊断为内痔脾虚气陷证,其证候:肛门松弛,痔核脱出须手法复位,便血色鲜或淡:面白少华,神疲乏力,少气懒言,纳少便溏:舌质淡,边有齿痕,苔薄白,脉弱。治法:补中益气。方药:补中益气汤加减。"},{"id":"2018-U0-087","unit":0,"number":87,"type":"A1/A2","stem":"患者,女,26岁,产后15天,寒热时作,热势不退,小腹疼痛拒按,恶露量多,色紫暗,气臭秽,心烦囗渴,尿少量黄,大便燥结,舌红紫,苔黄,脉涩或数,治法是","options":{"A":"清热解毒,凉血化瘀","B":"血热逐瘀,化脓散结","C":"养血祛风,疏解表邪","D":"活血化瘀,和营退热","E":"补血益气,和营退热"},"answer":"D","explanation":"根据患者的临床表现诊断为产后发热血瘀证,其主要证候:产后寒热时作,恶露不下或下亦甚少,色紫暗有块,小腹疼痛拒按;舌质紫暗或有瘀点,脉弦涩。治法:活血化瘀,和营退热。方药:生化汤加味或桃红消瘀汤。"},{"id":"2018-U0-088","unit":0,"number":88,"type":"A1/A2","stem":"患者,女27岁,己婚,产后恶露35天不止,量时多时少,色黯有块,小腹疼痛拒按,舌紫暗,边有瘀点,脉沉涩,治疗应首选的方剂是","options":{"A":"生化汤","B":"血府逐瘀汤","C":"膈下逐瘀汤","D":"少腹逐瘀汤","E":"桃红四物汤"},"answer":"A","explanation":"以解析〗根据患者的临床表现诊断为产后恶露不绝血瘀证,主要证候:恶露过期不尽,量时多或时少,色暗有块,小腹疼痛拒按;舌紫暗或边有瘀点,脉沉涩。治法:活血化瘀止血。方药:生化汤加益母草炒蒲黄。"},{"id":"2018-U0-089","unit":0,"number":89,"type":"A1/A2","stem":"患者女,23岁。有慢性贫血史2年,近半年乏力,心悸加重,血常规示红细胞22×1012/L,血红蛋白56g/L,白细胞25×109/L,血小板48.0×109/L,骨髓活组织检查示多部位增生重度低下,造血细胞减少,应首选的治疗药物是","options":{"A":"促红细胞生成素","B":"丙酸睾酮","C":"硫酸亚铁片","D":"抗胸腺球蛋白","E":"泼尼松龙"},"answer":"B","explanation":"根绝患者的临床表现及体征可诊断为再生障碍性贫血。再生障碍性贫血是由多种病因引起的原发性骨髓造血功能衰竭综合征,临床主要表现为骨髓造血功能低下、全血细胞减少和贫血、出血、感染。骨髓多部位增生减低,造血细胞减少符合再障的诊断标准。雄激素为治疗再障的首选药物。治疗机制:.增加促红细胞生成素(EPO)的产生,并加强造血干细胞对EPO的敏感性:@促进多能干细胞增殖和分化。常用药物有司坦唑醇、十一酸睾酮、达那唑、内酸睾酮等。"},{"id":"2018-U0-090","unit":0,"number":90,"type":"A1/A2","stem":"患者,男,41岁。因眼睑浮肿4个月就诊,查体:血压140/95mmHg,尿常规检查蛋白(+),红细胞镜检10、15个/HP,白细胞0、2个/HP,尿比重I.020,尿pH6.5;血常规检查未见异常,应首先考虑的诊断是","options":{"A":"慢性肾盂肾炎","B":"急性肾盂肾炎","C":"急性肾小球肾炎","D":"慢性肾小球肾炎","E":"慢病综合征"},"answer":"D","explanation":"根据患者的临床表现诊断为慢性肾小球肾炎,其可发生于任何年龄,但以中青年为主。临床表现呈多样性,早期患者可有乏力、疲倦、腰部疼痛、纳差等,以血尿、蛋白尿、高血压和水肿为基本临床表现。"},{"id":"2018-U0-091","unit":0,"number":91,"type":"A1/A2","stem":"患者,女,因活动后心悸就诊,查血常规示血红蛋白62G/L,平均红细胞体积62fl,平均红细胞血红蛋白浓度28%,血清铁5.9mo]./L,总铁结合力68umol/L,血清铁蛋白3g/L,考虑的诊断是","options":{"A":"缺铁性贫血","B":"再生障碍性贫血","C":"溶血性贫血","D":"巨幼细胞性贫血","E":"铁幼粒细胞性贫血"},"answer":"A","explanation":"根据患者的临床表现诊断为缺铁性贫血。诊断依据:有明确的缺铁病因和临床表现:小细胞低色素性贫血,MCV低于80f1,MCHC低于32%:血清铁低于8.9厚mol/L,总铁结合力高于64.4mo]./L,转铁蛋白饱和度低于15%;血清铁蛋白低于12ug/L,FEP/Hb高于4.5g/gHb;骨髓铁染色显示骨髓小粒可染铁消失。"},{"id":"2018-U0-092","unit":0,"number":92,"type":"A3","stem":"患者,女,60岁,有反复尿路感染病史5年,3天前因劳累而复发,发症:小便淋沥不己,尿感湿痛,时作时止,伴腰膝酸软,神疲乏力,舌淡,脉细弱。 其辨证是","options":{"A":"热淋","B":"血淋","C":"气淋","D":"膏淋","E":"劳淋"},"answer":"E","explanation":"根据患者的临床表现诊断为淋证劳淋,其证候:小便不甚赤涩,溺痛不甚,但淋沥不己,时作时止,遇劳即发,腰膝酸软,神疲乏力,病程缠绵,舌质淡,脉细弱。","prompt":"其辨证是","sharedStem":"患者,女,60岁,有反复尿路感染病史5年,3天前因劳累而复发,发症:小便淋沥不己,尿感湿痛,时作时止,伴腰膝酸软,神疲乏力,舌淡,脉细弱。","groupId":"2018-U0-A3-092-094","groupStart":92,"groupEnd":94},{"id":"2018-U0-093","unit":0,"number":93,"type":"A3","stem":"患者,女,60岁,有反复尿路感染病史5年,3天前因劳累而复发,发症:小便淋沥不己,尿感湿痛,时作时止,伴腰膝酸软,神疲乏力,舌淡,脉细弱。 其治法是","options":{"A":"补气益血","B":"补脾益肾","C":"补益肝肾","D":"健脾补肺","E":"补肺益肾"},"answer":"B","explanation":"劳淋证机概要:湿热留恋,脾肾两虚,膀胱气化无权。治法:补脾益肾。代表方《《《无比山药丸加减。","prompt":"其治法是","sharedStem":"患者,女,60岁,有反复尿路感染病史5年,3天前因劳累而复发,发症:小便淋沥不己,尿感湿痛,时作时止,伴腰膝酸软,神疲乏力,舌淡,脉细弱。","groupId":"2018-U0-A3-092-094","groupStart":92,"groupEnd":94},{"id":"2018-U0-094","unit":0,"number":94,"type":"A3","stem":"患者,女,60岁,有反复尿路感染病史5年,3天前因劳累而复发,发症:小便淋沥不己,尿感湿痛,时作时止,伴腰膝酸软,神疲乏力,舌淡,脉细弱。 治疗应首选的方剂是","options":{"A":"无比山药丸","B":"八珍汤","C":"河车大造丸","D":"金匮肾气丸","E":"附子理中丸"},"answer":"A","explanation":"劳淋证机概要:湿热留恋,脾肾两虚,膀胱气化无权。代表方:无比山药丸加减。常用药:党参、黄芪《怀山药、莲子肉、茯苓、薏苡仁、泽泻、扁豆衣、山茱萸、菟丝子、芡实、金樱子、煅牡蛎。","prompt":"治疗应首选的方剂是","sharedStem":"患者,女,60岁,有反复尿路感染病史5年,3天前因劳累而复发,发症:小便淋沥不己,尿感湿痛,时作时止,伴腰膝酸软,神疲乏力,舌淡,脉细弱。","groupId":"2018-U0-A3-092-094","groupStart":92,"groupEnd":94},{"id":"2018-U0-095","unit":0,"number":95,"type":"A3","stem":"患者,女,28岁,己婚,近3月来每逢经前出现小腹灼热胀痛,拒按,经色暗红,质稠有块,平素带下量多色黄,小腹疼痛,经来疼痛加剧,经前低热,小便黄赤,舌紫红,苔黄而腻,脉滑数。 其辨证是","options":{"A":"肝郁血热证","B":"阳盛血热证","C":"血热互结证","D":"湿热瘀阻证","E":"气滞血瘀证"},"answer":"D","explanation":"根据患者的临床表现诊断为痛经湿热瘀阻证,主要证候:经前或经期小腹疼痛或胀痛不适,有灼热感,或痛连腰骶,或平时小腹疼痛,经前加剧:经血量多或经期长,色暗红,质稠或夹较多黏液:平素带下量多”色黄质稠有臭味;或伴有低热起伏,小便黄赤;舌质红苔黄腻,脉滑数或弦数。","prompt":"其辨证是","sharedStem":"患者,女,28岁,己婚,近3月来每逢经前出现小腹灼热胀痛,拒按,经色暗红,质稠有块,平素带下量多色黄,小腹疼痛,经来疼痛加剧,经前低热,小便黄赤,舌紫红,苔黄而腻,脉滑数。","groupId":"2018-U0-A3-095-097","groupStart":95,"groupEnd":97},{"id":"2018-U0-096","unit":0,"number":96,"type":"A3","stem":"患者,女,28岁,己婚,近3月来每逢经前出现小腹灼热胀痛,拒按,经色暗红,质稠有块,平素带下量多色黄,小腹疼痛,经来疼痛加剧,经前低热,小便黄赤,舌紫红,苔黄而腻,脉滑数。 其治法有","options":{"A":"清热除湿,化瘀止痛","B":"清热解毒,行气止痛","C":"活血化瘀,理气止痛","D":"清热利湿,化瘀散结","E":"清热利湿,解毒排放"},"answer":"A","explanation":"痛经湿热瘀阻证治法:清热除湿,化瘀止痛。方药:清热调血汤加车前子、薏苡仁、败酱草或银甲丸。","prompt":"其治法有","sharedStem":"患者,女,28岁,己婚,近3月来每逢经前出现小腹灼热胀痛,拒按,经色暗红,质稠有块,平素带下量多色黄,小腹疼痛,经来疼痛加剧,经前低热,小便黄赤,舌紫红,苔黄而腻,脉滑数。","groupId":"2018-U0-A3-095-097","groupStart":95,"groupEnd":97},{"id":"2018-U0-097","unit":0,"number":97,"type":"A3","stem":"患者,女,28岁,己婚,近3月来每逢经前出现小腹灼热胀痛,拒按,经色暗红,质稠有块,平素带下量多色黄,小腹疼痛,经来疼痛加剧,经前低热,小便黄赤,舌紫红,苔黄而腻,脉滑数。 治疗应首选的方剂是","options":{"A":"止带方","B":"仙方活命饮","C":"血府逐瘀汤","D":"龙胆泻肝汤","E":"清热调血汤"},"answer":"E","explanation":"痛经湿热瘀阻证治法:清热除湿,化瘀止痛。方药:清热调血汤加车前子、薏苡仁、败酱草或银甲丸。","prompt":"治疗应首选的方剂是","sharedStem":"患者,女,28岁,己婚,近3月来每逢经前出现小腹灼热胀痛,拒按,经色暗红,质稠有块,平素带下量多色黄,小腹疼痛,经来疼痛加剧,经前低热,小便黄赤,舌紫红,苔黄而腻,脉滑数。","groupId":"2018-U0-A3-095-097","groupStart":95,"groupEnd":97},{"id":"2018-U0-098","unit":0,"number":98,"type":"A3","stem":"患丿L,女,9个月,1个月前患肺炎一直未愈,现干咳少痰,微喘,低热盗汗,囗唇干燥,大便硬结,舌红花剥,指纹淡紫显于气关。 其辨证是","options":{"A":"肺脾阴虚证","B":"营卫失调证","C":"肺肾阳虚证","D":"肺脾气虚证","E":"阴虚肺热证"},"answer":"E","explanation":"根据患者的临床表现诊断为小丿L肺炎喘嗽阴虚肺热证,证候:咳喘持久,低热盗汗,手足心热,干咳少痰,面色潮红,口干便结,舌红少津,苔少或花剥,脉细数,指纹淡紫。","prompt":"其辨证是","sharedStem":"患丿L,女,9个月,1个月前患肺炎一直未愈,现干咳少痰,微喘,低热盗汗,囗唇干燥,大便硬结,舌红花剥,指纹淡紫显于气关。","groupId":"2018-U0-A3-098-100","groupStart":98,"groupEnd":100},{"id":"2018-U0-099","unit":0,"number":99,"type":"A3","stem":"患丿L,女,9个月,1个月前患肺炎一直未愈,现干咳少痰,微喘,低热盗汗,囗唇干燥,大便硬结,舌红花剥,指纹淡紫显于气关。 其治法是","options":{"A":"养阴润肺,益气健脾","B":"调和营卫,益气固表","C":"养阴清热,敛肺止咳","D":"养阴清肺,润肺止咳","E":"补脾益气,健脾化瘀"},"answer":"D","explanation":"小丿L肺炎喘嗽阴虚肺热证治法:养阴清肺,润肺止咳。代表方剂:沙参麦冬汤。","prompt":"其治法是","sharedStem":"患丿L,女,9个月,1个月前患肺炎一直未愈,现干咳少痰,微喘,低热盗汗,囗唇干燥,大便硬结,舌红花剥,指纹淡紫显于气关。","groupId":"2018-U0-A3-098-100","groupStart":98,"groupEnd":100},{"id":"2018-U0-100","unit":0,"number":100,"type":"A3","stem":"患丿L,女,9个月,1个月前患肺炎一直未愈,现干咳少痰,微喘,低热盗汗,囗唇干燥,大便硬结,舌红花剥,指纹淡紫显于气关。 治疗应首选的方剂是","options":{"A":"生脉散","B":"沙参麦冬汤","C":"麦味地黄丸","D":"人参五味子汤","E":"黄芪桂枝五物汤"},"answer":"B","explanation":"小丿L肺炎喘嗽阴虚肺热证治法:养阴清肺,润肺止咳。代表方剂:沙参麦冬汤。","prompt":"治疗应首选的方剂是","sharedStem":"患丿L,女,9个月,1个月前患肺炎一直未愈,现干咳少痰,微喘,低热盗汗,囗唇干燥,大便硬结,舌红花剥,指纹淡紫显于气关。","groupId":"2018-U0-A3-098-100","groupStart":98,"groupEnd":100},{"id":"2018-U0-101","unit":0,"number":101,"type":"B1","stem":"上述各项,属阳中之阳的是","options":{"A":"上午","B":"下午","C":"中午","D":"前半夜","E":"后半夜"},"answer":"A","explanation":"以解析〗昼夜阴阳属性的一般说法是:上午属阳中之阳一。下午属阳中之阴,前半夜属阴中之阴,后半夜属阴中之阳。","prompt":"上述各项,属阳中之阳的是","sharedOptions":{"A":"上午","B":"下午","C":"中午","D":"前半夜","E":"后半夜"},"groupId":"2018-U0-B1-101-102","groupStart":101,"groupEnd":102},{"id":"2018-U0-102","unit":0,"number":102,"type":"B1","stem":"上述各项,属阴中之阴的是","options":{"A":"上午","B":"下午","C":"中午","D":"前半夜","E":"后半夜"},"answer":"D","explanation":"昼夜阴阳属性的一般说法是:上午属阳中之阳,下午属阳中之阴,前半夜属阴中之阴,后半夜属阴中之阳。","prompt":"上述各项,属阴中之阴的是","sharedOptions":{"A":"上午","B":"下午","C":"中午","D":"前半夜","E":"后半夜"},"groupId":"2018-U0-B1-101-102","groupStart":101,"groupEnd":102},{"id":"2018-U0-103","unit":0,"number":103,"type":"B1","stem":"具有“主行水”生理功能的脏是","options":{"A":"肺","B":"肾","C":"肝","D":"心","E":"脾"},"answer":"A","explanation":"肺圭行水,。指肺气的宣发肃降作用,疏通和调节着全身水液的输布和排泄。","prompt":"具有“主行水”生理功能的脏是","sharedOptions":{"A":"肺","B":"肾","C":"肝","D":"心","E":"脾"},"groupId":"2018-U0-B1-103-104","groupStart":103,"groupEnd":104},{"id":"2018-U0-104","unit":0,"number":104,"type":"B1","stem":"具有“主水”生理功能的脏是","options":{"A":"肺","B":"肾","C":"肝","D":"心","E":"脾"},"answer":"B","explanation":"肾主水液,主要指肾中精气的气化功能,对于体内津液的输布和排泄、维持体内津液代谢的平衡起着极为重要的调节作用。","prompt":"具有“主水”生理功能的脏是","sharedOptions":{"A":"肺","B":"肾","C":"肝","D":"心","E":"脾"},"groupId":"2018-U0-B1-103-104","groupStart":103,"groupEnd":104},{"id":"2018-U0-105","unit":0,"number":105,"type":"B1","stem":"“筋之余”指的是","options":{"A":"面","B":"毛","C":"唇","D":"爪","E":"发"},"answer":"D","explanation":"肝其华在爪:爪,即爪甲,包括指甲和趾甲,乃筋之延续,故称“爪为筋之余”肝血的盛衰,可影响爪甲的荣枯。","prompt":"“筋之余”指的是","sharedOptions":{"A":"面","B":"毛","C":"唇","D":"爪","E":"发"},"groupId":"2018-U0-B1-105-106","groupStart":105,"groupEnd":106},{"id":"2018-U0-106","unit":0,"number":106,"type":"B1","stem":"“血之余”指的是","options":{"A":"面","B":"毛","C":"唇","D":"爪","E":"发"},"answer":"E","explanation":"肾其华在发:发的生长,全赖于精和血。发的生长与脱落、润泽与枯槁,不仅依赖于肾中精气之充养,而且有赖于血液的濡养,故称“发为血之余”","prompt":"“血之余”指的是","sharedOptions":{"A":"面","B":"毛","C":"唇","D":"爪","E":"发"},"groupId":"2018-U0-B1-105-106","groupStart":105,"groupEnd":106},{"id":"2018-U0-107","unit":0,"number":107,"type":"B1","stem":"上述各项,具有“主津”功能的是","options":{"A":"胃","B":"小肠","C":"大肠","D":"膀胱","E":"三焦"},"answer":"C","explanation":"大肠接受山小肠传下的含有大量水液的食物残渣,将其中的水液吸收,使之形成粪便,即所谓燥化作用。大肠吸收水液,参与体内的水液代谢,故说“大肠主津”","prompt":"上述各项,具有“主津”功能的是","sharedOptions":{"A":"胃","B":"小肠","C":"大肠","D":"膀胱","E":"三焦"},"groupId":"2018-U0-B1-107-108","groupStart":107,"groupEnd":108},{"id":"2018-U0-108","unit":0,"number":108,"type":"B1","stem":"上述各项,具有“主液”功能的是","options":{"A":"胃","B":"小肠","C":"大肠","D":"膀胱","E":"三焦"},"answer":"B","explanation":"小肠在吸收水谷精微的同时,也吸收了大量的水液,故又称“小肠主液”","prompt":"上述各项,具有“主液”功能的是","sharedOptions":{"A":"胃","B":"小肠","C":"大肠","D":"膀胱","E":"三焦"},"groupId":"2018-U0-B1-107-108","groupStart":107,"groupEnd":108},{"id":"2018-U0-109","unit":0,"number":109,"type":"B1","stem":"气的功能中,与激发人体生长发育机能关系密切的是","options":{"A":"中介作用","B":"防御作用","C":"固摄作用","D":"推动与调控作用","E":"温煦与凉润作用"},"answer":"D","explanation":"气的推动作用,指气中属阳部分(阳气)的激发、兴奋、促进等作用。主要体现于:.激发和促进人体的生长发育及生殖机能。@激发和促进各脏腑经络的生理机能。@激发和促进精血津液的生成及运行输布。@激发和、、奋精神活动。","prompt":"气的功能中,与激发人体生长发育机能关系密切的是","sharedOptions":{"A":"中介作用","B":"防御作用","C":"固摄作用","D":"推动与调控作用","E":"温煦与凉润作用"},"groupId":"2018-U0-B1-109-110","groupStart":109,"groupEnd":110},{"id":"2018-U0-110","unit":0,"number":110,"type":"B1","stem":"气的功能中,与维持人体相对恒定体温关系密切的是","options":{"A":"中介作用","B":"防御作用","C":"固摄作用","D":"推动与调控作用","E":"温煦与凉润作用"},"answer":"E","explanation":"气的温煦作用,指气中属阳部分(阳气)的促进产热,消除寒冷,使人体温暖的作用。气的温煦作用对人体有重要的生理意义:.温煦机体,维持相对恒定的体温訂@温煦各脏腑、经络、形体《官窍,助其进行正常的生理活动。0温煦精血津液,助其正常施泄、循行、输布,即所谓“得温而行,得寒而凝”","prompt":"气的功能中,与维持人体相对恒定体温关系密切的是","sharedOptions":{"A":"中介作用","B":"防御作用","C":"固摄作用","D":"推动与调控作用","E":"温煦与凉润作用"},"groupId":"2018-U0-B1-109-110","groupStart":109,"groupEnd":110},{"id":"2018-U0-111","unit":0,"number":111,"type":"B1","stem":"与血液生成关系较为密切的脏是","options":{"A":"心肺肝脾","B":"心肾肝脾","C":"肺肾心脾","D":"肝肾心肺","E":"肾脾肝肺"},"answer":"C","explanation":"脾胃是血液生化之源:脾胃运化的水谷精微所产生的营气和津液,是化生血液的主要物质。@心肺对血液的生成起重要作用:脾胃运化水谷精微所化生的营气和津液,由脾向上升输于心肺,与肺吸入的清气相结合,贯注心脉,在心气的作用下变化而成为红色血液。@肾藏精,精生髓,精髓是化生血液的基本物质之一。同时。肾精充足,肾气充沛,也可以促进脾胃的运化,有助于血液的化生。","prompt":"与血液生成关系较为密切的脏是","sharedOptions":{"A":"心肺肝脾","B":"心肾肝脾","C":"肺肾心脾","D":"肝肾心肺","E":"肾脾肝肺"},"groupId":"2018-U0-B1-111-112","groupStart":111,"groupEnd":112},{"id":"2018-U0-112","unit":0,"number":112,"type":"B1","stem":"与血液运行关系较为密切的脏是","options":{"A":"心肺肝脾","B":"心肾肝脾","C":"肺肾心脾","D":"肝肾心肺","E":"肾脾肝肺"},"answer":"A","explanation":"心、肝、脾、肺等脏生理机能的相互协调与密切配合,共同保证了血液的正常运行。心阳的推动和温煦、肺气的宣发与肃降、肝气的疏泄是推动和促进血液运行的重要因素:心阴的宁静与凉润、脾气的统摄、肝气的藏血是控制和固摄血液运行的重要因素。","prompt":"与血液运行关系较为密切的脏是","sharedOptions":{"A":"心肺肝脾","B":"心肾肝脾","C":"肺肾心脾","D":"肝肾心肺","E":"肾脾肝肺"},"groupId":"2018-U0-B1-111-112","groupStart":111,"groupEnd":112},{"id":"2018-U0-113","unit":0,"number":113,"type":"B1","stem":"依据十二经络脉流注规律,手足阳经交接部位是","options":{"A":"胸部","B":"头面部","C":"项背部","D":"下肢末端","E":"上肢末端"},"answer":"B","explanation":"同名的阳经与阳经在头面部交接,如手足阳明经交接于鼻旁,手足太阳经交接于目内眦,手足少阳经交接于目外眦。","prompt":"依据十二经络脉流注规律,手足阳经交接部位是","sharedOptions":{"A":"胸部","B":"头面部","C":"项背部","D":"下肢末端","E":"上肢末端"},"groupId":"2018-U0-B1-113-114","groupStart":113,"groupEnd":114},{"id":"2018-U0-114","unit":0,"number":114,"type":"B1","stem":"依据十二经脉流注规律,手足阴经交接部位是","options":{"A":"胸部","B":"头面部","C":"项背部","D":"下肢末端","E":"上肢末端"},"answer":"A","explanation":"相互衔接的阴经与阴经在胸中交接,如足太阴经与手少阴经交接于心中。","prompt":"依据十二经脉流注规律,手足阴经交接部位是","sharedOptions":{"A":"胸部","B":"头面部","C":"项背部","D":"下肢末端","E":"上肢末端"},"groupId":"2018-U0-B1-113-114","groupStart":113,"groupEnd":114},{"id":"2018-U0-115","unit":0,"number":115,"type":"B1","stem":"上述各项,其致病易成“行痹”的是","options":{"A":"风","B":"寒","C":"暑","D":"湿","E":"火"},"answer":"A","explanation":"风气胜者为行痹,寒气胜者为痛痹,湿气胜者为着痹也。","prompt":"上述各项,其致病易成“行痹”的是","sharedOptions":{"A":"风","B":"寒","C":"暑","D":"湿","E":"火"},"groupId":"2018-U0-B1-115-116","groupStart":115,"groupEnd":116},{"id":"2018-U0-116","unit":0,"number":116,"type":"B1","stem":"上述各项,其致病易成“痛痹”的是","options":{"A":"风","B":"寒","C":"暑","D":"湿","E":"火"},"answer":"B","explanation":"风气胜者为行痹,寒气胜者为痛痹,湿气胜者为着痹也。","prompt":"上述各项,其致病易成“痛痹”的是","sharedOptions":{"A":"风","B":"寒","C":"暑","D":"湿","E":"火"},"groupId":"2018-U0-B1-115-116","groupStart":115,"groupEnd":116},{"id":"2018-U0-117","unit":0,"number":117,"type":"B1","stem":"七情内伤影响脏腑气机,导致“气上”的是","options":{"A":"怒","B":"喜","C":"悲","D":"思","E":"恐"},"answer":"A","explanation":"百病生于气也,怒则气上,喜则气缓,悲则气消,恐则气下,惊则气乱,思则气结。","prompt":"七情内伤影响脏腑气机,导致“气上”的是","sharedOptions":{"A":"怒","B":"喜","C":"悲","D":"思","E":"恐"},"groupId":"2018-U0-B1-117-118","groupStart":117,"groupEnd":118},{"id":"2018-U0-118","unit":0,"number":118,"type":"B1","stem":"七情内伤影响脏腑气机,导致“气下”的是","options":{"A":"怒","B":"喜","C":"悲","D":"思","E":"恐"},"answer":"E","explanation":"百病生于气也,怒则气上,喜则气缓,悲则气消,恐则气下,惊则气乱,思则气结。","prompt":"七情内伤影响脏腑气机,导致“气下”的是","sharedOptions":{"A":"怒","B":"喜","C":"悲","D":"思","E":"恐"},"groupId":"2018-U0-B1-117-118","groupStart":117,"groupEnd":118},{"id":"2018-U0-119","unit":0,"number":119,"type":"B1","stem":"肝郁脾虚的面色是","options":{"A":"面白浮肿","B":"面色青紫","C":"面色苍黄","D":"面色黧黑","E":"面色萎黄"},"answer":"C","explanation":"面色青黄(苍黄),多属肝郁脾虚、血瘀水停0可见于鼓胀或胁下癥积的患者。","prompt":"肝郁脾虚的面色是","sharedOptions":{"A":"面白浮肿","B":"面色青紫","C":"面色苍黄","D":"面色黧黑","E":"面色萎黄"},"groupId":"2018-U0-B1-119-120","groupStart":119,"groupEnd":120},{"id":"2018-U0-120","unit":0,"number":120,"type":"B1","stem":"脾胃气虚的面色是","options":{"A":"面白浮肿","B":"面色青紫","C":"面色苍黄","D":"面色黧黑","E":"面色萎黄"},"answer":"E","explanation":"面色淡黄,枯槁无华,称“萎黄”常见于脾胃气虚,气血不足者。","prompt":"脾胃气虚的面色是","sharedOptions":{"A":"面白浮肿","B":"面色青紫","C":"面色苍黄","D":"面色黧黑","E":"面色萎黄"},"groupId":"2018-U0-B1-119-120","groupStart":119,"groupEnd":120},{"id":"2018-U0-121","unit":0,"number":121,"type":"B1","stem":"寒湿内侵,络脉血瘀所致的临床表现是","options":{"A":"四肢萎缩","B":"肢体肿胀","C":"膝部肿大","D":"小腿青筋","E":"下肢畸形"},"answer":"D","explanation":"小腿青筋暴露,形似蚯蚓。多因寒湿内侵,络脉血瘀所致。","prompt":"寒湿内侵,络脉血瘀所致的临床表现是","sharedOptions":{"A":"四肢萎缩","B":"肢体肿胀","C":"膝部肿大","D":"小腿青筋","E":"下肢畸形"},"groupId":"2018-U0-B1-121-122","groupStart":121,"groupEnd":122},{"id":"2018-U0-122","unit":0,"number":122,"type":"B1","stem":"气血亏虚,肢体失养所致的临床表现是","options":{"A":"四肢萎缩","B":"肢体肿胀","C":"膝部肿大","D":"小腿青筋","E":"下肢畸形"},"answer":"A","explanation":"四肢萎缩指四肢或某一肢体肌肉消瘦、萎缩、松软无力。多因气血亏虚或经络闭阻,肢体失养所致。","prompt":"气血亏虚,肢体失养所致的临床表现是","sharedOptions":{"A":"四肢萎缩","B":"肢体肿胀","C":"膝部肿大","D":"小腿青筋","E":"下肢畸形"},"groupId":"2018-U0-B1-121-122","groupStart":121,"groupEnd":122},{"id":"2018-U0-123","unit":0,"number":123,"type":"B1","stem":"舌淡红中泛现青紫,其临床意义是","options":{"A":"气机不畅","B":"脾虚湿侵","C":"药物中毒","D":"阴虚火旺","E":"痰饮内停"},"answer":"C","explanation":"舌色淡红中泛现青紫:多因肺气壅滞,或肝郁血瘀,亦可见于先天性心脏病,或某些药物、食物中毒。","prompt":"舌淡红中泛现青紫,其临床意义是","sharedOptions":{"A":"气机不畅","B":"脾虚湿侵","C":"药物中毒","D":"阴虚火旺","E":"痰饮内停"},"groupId":"2018-U0-B1-123-124","groupStart":123,"groupEnd":124},{"id":"2018-U0-124","unit":0,"number":124,"type":"B1","stem":"舌淡白胖嫩,边有齿痕和裂纹,其临床意义是","options":{"A":"气机不畅","B":"脾虚湿侵","C":"药物中毒","D":"阴虚火旺","E":"痰饮内停"},"answer":"B","explanation":"舌淡白而有裂纹:多为血虚不润。舌淡白胖嫩,边有齿痕而又有裂纹:属脾虚湿侵。","prompt":"舌淡白胖嫩,边有齿痕和裂纹,其临床意义是","sharedOptions":{"A":"气机不畅","B":"脾虚湿侵","C":"药物中毒","D":"阴虚火旺","E":"痰饮内停"},"groupId":"2018-U0-B1-123-124","groupStart":123,"groupEnd":124},{"id":"2018-U0-125","unit":0,"number":125,"type":"B1","stem":"阴经郁热熏蒸可见的汗是","options":{"A":"头汗","B":"半身汗","C":"手足心汗","D":"阴汗","E":"心胸汗"},"answer":"C","explanation":"手足心汗指病人手足心汗出较多的症状。可因阴经郁热熏蒸,或阳明燥热内结,或脾虚运化失常,阴虚阳亢或中焦湿热郁蒸,或阳气内郁所致。","prompt":"阴经郁热熏蒸可见的汗是","sharedOptions":{"A":"头汗","B":"半身汗","C":"手足心汗","D":"阴汗","E":"心胸汗"},"groupId":"2018-U0-B1-125-126","groupStart":125,"groupEnd":126},{"id":"2018-U0-126","unit":0,"number":126,"type":"B1","stem":"上焦热盛可见的汗是","options":{"A":"头汗","B":"半身汗","C":"手足心汗","D":"阴汗","E":"心胸汗"},"answer":"A","explanation":"头汗指病人仅头部或头颈部出汗较多,又称为“但头汗出”。多因上焦热盛,或中焦湿热蕴结,或病危虚阳上越,或进食辛辣、热汤,饮酒,使阳气旺盛,热蒸于头。","prompt":"上焦热盛可见的汗是","sharedOptions":{"A":"头汗","B":"半身汗","C":"手足心汗","D":"阴汗","E":"心胸汗"},"groupId":"2018-U0-B1-125-126","groupStart":125,"groupEnd":126},{"id":"2018-U0-127","unit":0,"number":127,"type":"B1","stem":"肝胃蕴热可见的口味是","options":{"A":"口淡乏味","B":"口甜黏腻","C":"口咸","D":"口中泛酸","E":"口苦"},"answer":"D","explanation":"口酸是指病人自觉口中有酸味,或泛酸。多因肝胃郁热或饮食停滞所致。","prompt":"肝胃蕴热可见的口味是","sharedOptions":{"A":"口淡乏味","B":"口甜黏腻","C":"口咸","D":"口中泛酸","E":"口苦"},"groupId":"2018-U0-B1-127-128","groupStart":127,"groupEnd":128},{"id":"2018-U0-128","unit":0,"number":128,"type":"B1","stem":"湿热蕴脾可见的口味是","options":{"A":"口淡乏味","B":"口甜黏腻","C":"口咸","D":"口中泛酸","E":"口苦"},"answer":"B","explanation":"口黏腻是指病人自觉口中黏腻不爽的症状。常见于痰热内盛、湿热蕴脾及寒湿困脾之证。口中甜而胶黏,脘闷不舒,舌苔黄腻者,为脾胃湿热。因湿热内阻,脾胃升降失职是浊气上蒸,故见囗甜。","prompt":"湿热蕴脾可见的口味是","sharedOptions":{"A":"口淡乏味","B":"口甜黏腻","C":"口咸","D":"口中泛酸","E":"口苦"},"groupId":"2018-U0-B1-127-128","groupStart":127,"groupEnd":128},{"id":"2018-U0-129","unit":0,"number":129,"type":"B1","stem":"脉沉细无力而软的临床意义是","options":{"A":"阴虚","B":"阳虚","C":"寒证","D":"热证","E":"湿困"},"answer":"B","explanation":"弱脉沉细无力而软。其脉象特征是位沉、形细、势软。由于脉管细小不充盈,其搏动部位在皮肉之下靠近筋骨处,指下感到细而无。弱脉多见于阳气虚衰、气血俱虚。","prompt":"脉沉细无力而软的临床意义是","sharedOptions":{"A":"阴虚","B":"阳虚","C":"寒证","D":"热证","E":"湿困"},"groupId":"2018-U0-B1-129-130","groupStart":129,"groupEnd":130},{"id":"2018-U0-130","unit":0,"number":130,"type":"B1","stem":"脉浮细无力而软的临床意义是","options":{"A":"阴虚","B":"阳虚","C":"寒证","D":"热证","E":"湿困"},"answer":"E","explanation":"濡脉浮细无力而软。其脉象特征是位浮、形细、势软。其脉管搏动的部位在浅层,形细而软,如絮浮水,轻取即得,重按不显濡脉多见于虚证或湿困。","prompt":"脉浮细无力而软的临床意义是","sharedOptions":{"A":"阴虚","B":"阳虚","C":"寒证","D":"热证","E":"湿困"},"groupId":"2018-U0-B1-129-130","groupStart":129,"groupEnd":130},{"id":"2018-U0-131","unit":0,"number":131,"type":"B1","stem":"“寒包火”证属于八纲证候间的关系是","options":{"A":"寒证转热证","B":"热证转寒证","C":"真热假寒证","D":"真寒假热证","E":"寒热错杂证"},"answer":"E","explanation":"八纲中表里寒热虚实的错杂关系,可以表现为表里同病、寒热错杂、虚实夹杂。其中,表里同病,虚实性质相同,但寒热性质相反的证候,如表实寒里实热证,即“寒包火”证。","prompt":"“寒包火”证属于八纲证候间的关系是","sharedOptions":{"A":"寒证转热证","B":"热证转寒证","C":"真热假寒证","D":"真寒假热证","E":"寒热错杂证"},"groupId":"2018-U0-B1-131-132","groupStart":131,"groupEnd":132},{"id":"2018-U0-132","unit":0,"number":132,"type":"B1","stem":"寒湿痹过服温燥药物而致局部红肿,属于八纲证候间的关系是","options":{"A":"寒证转热证","B":"热证转寒证","C":"真热假寒证","D":"真寒假热证","E":"寒热错杂证"},"answer":"A","explanation":"寒证化热常见于外感寒邪未及时发散,而机体阳气偏盛,阳热内郁到一定程度,寒邪化热,形成热证:或是寒湿之邪郁遏,而机体阳气不衰,由寒而化热:或因使用温燥之品太过,亦可使寒证转化为热证。","prompt":"寒湿痹过服温燥药物而致局部红肿,属于八纲证候间的关系是","sharedOptions":{"A":"寒证转热证","B":"热证转寒证","C":"真热假寒证","D":"真寒假热证","E":"寒热错杂证"},"groupId":"2018-U0-B1-131-132","groupStart":131,"groupEnd":132},{"id":"2018-U0-133","unit":0,"number":133,"type":"B1","stem":"风邪中络证的临床表现是","options":{"A":"恶风发热,汗出,脉浮缓","B":"肢体关节游走疼痛","C":"肌肤麻木,囗眼喁斜","D":"突起面睑浮肿,晨起尤重,伴发热恶寒","E":"咳嗽,咽喉痒痛,鼻塞,流鼻涕"},"answer":"C","explanation":"风邪或风毒侵袭经络、肌肤,经气阻滞,肌肤麻痹,则可出现肌肤麻木、囗眼喁斜等症,此为风邪中络证","prompt":"风邪中络证的临床表现是","sharedOptions":{"A":"恶风发热,汗出,脉浮缓","B":"肢体关节游走疼痛","C":"肌肤麻木,囗眼喁斜","D":"突起面睑浮肿,晨起尤重,伴发热恶寒","E":"咳嗽,咽喉痒痛,鼻塞,流鼻涕"},"groupId":"2018-U0-B1-133-134","groupStart":133,"groupEnd":134},{"id":"2018-U0-134","unit":0,"number":134,"type":"B1","stem":"风水相搏证的临床表现是","options":{"A":"恶风发热,汗出,脉浮缓","B":"肢体关节游走疼痛","C":"肌肤麻木,囗眼喁斜","D":"突起面睑浮肿,晨起尤重,伴发热恶寒","E":"咳嗽,咽喉痒痛,鼻塞,流鼻涕"},"answer":"D","explanation":"风邪侵犯肺卫,宣降失常,通调水道失职,则见突起面睑肢体浮肿,此为风水相搏","prompt":"风水相搏证的临床表现是","sharedOptions":{"A":"恶风发热,汗出,脉浮缓","B":"肢体关节游走疼痛","C":"肌肤麻木,囗眼喁斜","D":"突起面睑浮肿,晨起尤重,伴发热恶寒","E":"咳嗽,咽喉痒痛,鼻塞,流鼻涕"},"groupId":"2018-U0-B1-133-134","groupStart":133,"groupEnd":134},{"id":"2018-U0-135","unit":0,"number":135,"type":"B1","stem":"表现为长期便血,神疲乏力,舌淡脉弱,其证是","options":{"A":"气血两虚证","B":"气不摄血证","C":"气虚血瘀证","D":"气随血脱证","E":"气滞血瘀证"},"answer":"B","explanation":"气不摄血证是指气虚摄血无力,导致血溢脉外所产生的证候。临床表现:吐血、便血、崩漏、皮下瘀斑、鼻衄,神疲乏力,气短懒言,面色淡白,舌淡,脉弱。","prompt":"表现为长期便血,神疲乏力,舌淡脉弱,其证是","sharedOptions":{"A":"气血两虚证","B":"气不摄血证","C":"气虚血瘀证","D":"气随血脱证","E":"气滞血瘀证"},"groupId":"2018-U0-B1-135-136","groupStart":135,"groupEnd":136},{"id":"2018-U0-136","unit":0,"number":136,"type":"B1","stem":"一妇女痛经,经血紫暗有块,胸胁胀满疼痛,其证是","options":{"A":"气血两虚证","B":"气不摄血证","C":"气虚血瘀证","D":"气随血脱证","E":"气滞血瘀证"},"answer":"E","explanation":"气滞血瘀证是指气机郁滞,导致血行瘀阻所产生的证候。临床表现:胸胁胀满疼痛,乳房胀痛,情志抑郁或易怒,兼见痞块刺痛、拒按,妇女痛经,经血紫暗有块,或闭经,舌紫暗或有瘀点瘀斑,脉弦涩。","prompt":"一妇女痛经,经血紫暗有块,胸胁胀满疼痛,其证是","sharedOptions":{"A":"气血两虚证","B":"气不摄血证","C":"气虚血瘀证","D":"气随血脱证","E":"气滞血瘀证"},"groupId":"2018-U0-B1-135-136","groupStart":135,"groupEnd":136},{"id":"2018-U0-137","unit":0,"number":137,"type":"B1","stem":"表现为心悸健忘,失眠多梦,头晕目眩,面色苍白,肢体麻木的是","options":{"A":"心肝血虚证","B":"肝肾阴虚证","C":"肾肺阴虚证","D":"心肾不交证","E":"心脾气血虚证"},"answer":"A","explanation":"心肝血虚证临床表现:心悸心慌,多梦健忘,头晕目眩,视物模糊,肢体麻木、震颤,女子月经量少色淡,甚则经闭,面白无华,爪甲不荣,舌质淡白,脉细。","prompt":"表现为心悸健忘,失眠多梦,头晕目眩,面色苍白,肢体麻木的是","sharedOptions":{"A":"心肝血虚证","B":"肝肾阴虚证","C":"肾肺阴虚证","D":"心肾不交证","E":"心脾气血虚证"},"groupId":"2018-U0-B1-137-138","groupStart":137,"groupEnd":138},{"id":"2018-U0-138","unit":0,"number":138,"type":"B1","stem":"表现为腰膝酸软,五心烦热,失眠多梦,耳鸣目涩,遗精盗汗的是","options":{"A":"心肝血虚证","B":"肝肾阴虚证","C":"肾肺阴虚证","D":"心肾不交证","E":"心脾气血虚证"},"answer":"D","explanation":"心肾不交证临床表现:心烦失眠,惊悸健忘,头晕,耳鸣,腰膝酸软,梦遗,囗咽干燥,五心烦热,潮热盗汗,便结尿黄,舌红少苔,脉细数。","prompt":"表现为腰膝酸软,五心烦热,失眠多梦,耳鸣目涩,遗精盗汗的是","sharedOptions":{"A":"心肝血虚证","B":"肝肾阴虚证","C":"肾肺阴虚证","D":"心肾不交证","E":"心脾气血虚证"},"groupId":"2018-U0-B1-137-138","groupStart":137,"groupEnd":138},{"id":"2018-U0-139","unit":0,"number":139,"type":"B1","stem":"治疗风寒感冒,寒湿带下,应选用的药物是","options":{"A":"葛根","B":"荆芥","C":"生姜","D":"白芷","E":"淡豆豉"},"answer":"D","explanation":"白芷功效:解表散寒,祛风止痛,宣通鼻窍,燥湿止带,消肿排脓。主治:.风寒感冒。@头痛,牙痛,风湿痹痛。@鼻渊。@带下证。0疮痈肿毒。","prompt":"治疗风寒感冒,寒湿带下,应选用的药物是","sharedOptions":{"A":"葛根","B":"荆芥","C":"生姜","D":"白芷","E":"淡豆豉"},"groupId":"2018-U0-B1-139-140","groupStart":139,"groupEnd":140},{"id":"2018-U0-140","unit":0,"number":140,"type":"B1","stem":"治疗风寒感冒,肺寒咳嗽,应选用的药物是","options":{"A":"葛根","B":"荆芥","C":"生姜","D":"白芷","E":"淡豆豉"},"answer":"C","explanation":"生姜功效:解表散寒,温中止呕,温肺止咳,解鱼蟹毒。主治病证:一风寒感冒:脾胃寒证;胃寒呕吐;肺寒咳嗽。此外,能解生半夏、生南星和鱼蟹之毒。","prompt":"治疗风寒感冒,肺寒咳嗽,应选用的药物是","sharedOptions":{"A":"葛根","B":"荆芥","C":"生姜","D":"白芷","E":"淡豆豉"},"groupId":"2018-U0-B1-139-140","groupStart":139,"groupEnd":140},{"id":"2018-U0-141","unit":0,"number":141,"type":"B1","stem":"具有明目,散结消肿功效的药物是","options":{"A":"钩藤","B":"熊胆粉","C":"水牛角","D":"决明子","E":"夏枯草"},"answer":"E","explanation":"夏枯草性能:辛、苦,寒。归肝、胆经。功效:清热泻火,明目,散结消肿。","prompt":"具有明目,散结消肿功效的药物是","sharedOptions":{"A":"钩藤","B":"熊胆粉","C":"水牛角","D":"决明子","E":"夏枯草"},"groupId":"2018-U0-B1-141-142","groupStart":141,"groupEnd":142},{"id":"2018-U0-142","unit":0,"number":142,"type":"B1","stem":"具有明目,息风止痉功效的药物是","options":{"A":"钩藤","B":"熊胆粉","C":"水牛角","D":"决明子","E":"夏枯草"},"answer":"B","explanation":"熊胆粉功效:清热解毒,清肝明目,息风止痉。","prompt":"具有明目,息风止痉功效的药物是","sharedOptions":{"A":"钩藤","B":"熊胆粉","C":"水牛角","D":"决明子","E":"夏枯草"},"groupId":"2018-U0-B1-141-142","groupStart":141,"groupEnd":142},{"id":"2018-U0-143","unit":0,"number":143,"type":"B1","stem":"大黄治实热便秘,常配伍的药组是","options":{"A":"厚朴,枳实","B":"紫苏,陈皮","C":"石膏,知母","D":"薤白,青皮","E":"黄连,黄芩"},"answer":"A","explanation":"大黄功效:泻下攻积,清热泻火,凉血解毒,逐瘀通经,除湿退黄。其有较强的泻下作用,能荡涤肠胃,推陈致新,为治疗积滞便秘之要药。又因其苦寒沉降,善能泄热,故实热便秘尤为适宜。常与芒硝、厚朴、枳实配伍,以增强泻下攻积之力,为急下之剂。","prompt":"大黄治实热便秘,常配伍的药组是","sharedOptions":{"A":"厚朴,枳实","B":"紫苏,陈皮","C":"石膏,知母","D":"薤白,青皮","E":"黄连,黄芩"},"groupId":"2018-U0-B1-143-144","groupStart":143,"groupEnd":144},{"id":"2018-U0-144","unit":0,"number":144,"type":"B1","stem":"大黄治血热吐衄,常配伍的药组是","options":{"A":"厚朴,枳实","B":"紫苏,陈皮","C":"石膏,知母","D":"薤白,青皮","E":"黄连,黄芩"},"answer":"E","explanation":"大黄功效:泻下攻积,清热泻火,凉血解毒,逐瘀通经,除湿退黄。其苦降,能使上炎之火下泄,又具清热泻火、凉血止血之功。常与黄连、黄芩同用,治血热妄行之吐血、衄血、咯血,如泻心汤。","prompt":"大黄治血热吐衄,常配伍的药组是","sharedOptions":{"A":"厚朴,枳实","B":"紫苏,陈皮","C":"石膏,知母","D":"薤白,青皮","E":"黄连,黄芩"},"groupId":"2018-U0-B1-143-144","groupStart":143,"groupEnd":144},{"id":"2018-U0-145","unit":0,"number":145,"type":"B1","stem":"具有祛风湿,利水消肿功效的药物是","options":{"A":"独活","B":"川乌","C":"防己","D":"桑寄生","E":"络石藤"},"answer":"C","explanation":"防己性能:苦,寒。归膀胱、肺经。功效:祛风湿,止痛,利水消肿。","prompt":"具有祛风湿,利水消肿功效的药物是","sharedOptions":{"A":"独活","B":"川乌","C":"防己","D":"桑寄生","E":"络石藤"},"groupId":"2018-U0-B1-145-146","groupStart":145,"groupEnd":146},{"id":"2018-U0-146","unit":0,"number":146,"type":"B1","stem":"具有祛风湿,补肾安胎功效的药物是","options":{"A":"独活","B":"川乌","C":"防己","D":"桑寄生","E":"络石藤"},"answer":"D","explanation":"桑寄生性能:苦、甘,平。归肝、肾经。功效:祛风湿,补肝肾,强筋骨,安胎元。","prompt":"具有祛风湿,补肾安胎功效的药物是","sharedOptions":{"A":"独活","B":"川乌","C":"防己","D":"桑寄生","E":"络石藤"},"groupId":"2018-U0-B1-145-146","groupStart":145,"groupEnd":146},{"id":"2018-U0-147","unit":0,"number":147,"type":"B1","stem":"具有凉血止血,清肝泻火功效的药物是","options":{"A":"三七","B":"地榆","C":"槐花","D":"仙鹤草","E":"白茅根"},"answer":"C","explanation":"槐花功效:凉血止血,清肝泻火。主治病证:血热出血:肝热目赤,头痛眩晕。","prompt":"具有凉血止血,清肝泻火功效的药物是","sharedOptions":{"A":"三七","B":"地榆","C":"槐花","D":"仙鹤草","E":"白茅根"},"groupId":"2018-U0-B1-147-148","groupStart":147,"groupEnd":148},{"id":"2018-U0-148","unit":0,"number":148,"type":"B1","stem":"具有凉血止血,清热利尿功效的药物是","options":{"A":"三七","B":"地榆","C":"槐花","D":"仙鹤草","E":"白茅根"},"answer":"E","explanation":"白茅根功效:凉血止血,清热利尿。主治病证:血热出血:水肿,热淋,黄疸:胃热呕吐,肺热咳嗽。","prompt":"具有凉血止血,清热利尿功效的药物是","sharedOptions":{"A":"三七","B":"地榆","C":"槐花","D":"仙鹤草","E":"白茅根"},"groupId":"2018-U0-B1-147-148","groupStart":147,"groupEnd":148},{"id":"2018-U0-149","unit":0,"number":149,"type":"B1","stem":"治疗肺热咳嗽,肺痈肠痈,应选用的药物是","options":{"A":"竹茹","B":"白果","C":"半夏","D":"瓜蒌","E":"紫菀"},"answer":"D","explanation":"瓜蒌功效:清热涤痰,宽胸散结,润燥滑肠。应用:.痰热咳嗽。@胸痹、结胸。@肺痈,肠痈,乳痈。","prompt":"治疗肺热咳嗽,肺痈肠痈,应选用的药物是","sharedOptions":{"A":"竹茹","B":"白果","C":"半夏","D":"瓜蒌","E":"紫菀"},"groupId":"2018-U0-B1-149-150","groupStart":149,"groupEnd":150},{"id":"2018-U0-150","unit":0,"number":150,"type":"B1","stem":"治疗肺热咳嗽,胃热呕吐,应选用的药物是","options":{"A":"竹茹","B":"白果","C":"半夏","D":"瓜蒌","E":"紫菀"},"answer":"A","explanation":"竹茹功能:清热化痰,除烦,止呕。主治病证:一肺热咳嗽,痰热心烦不寐;胃热呕吐。妊娠恶阻。","prompt":"治疗肺热咳嗽,胃热呕吐,应选用的药物是","sharedOptions":{"A":"竹茹","B":"白果","C":"半夏","D":"瓜蒌","E":"紫菀"},"groupId":"2018-U0-B1-149-150","groupStart":149,"groupEnd":150},{"id":"2018-U0-151","unit":0,"number":151,"type":"B1","stem":"具有补肾阳,益精血功效的药组是","options":{"A":"补骨脂,益智仁","B":"淫羊盐,巴戟天","C":"沙苑子,淫羊盐","D":"杜仲,补骨脂","E":"鹿茸,巴戟天"},"answer":"E","explanation":"鹿茸功效:壮肾阳,益精血,强筋骨,调冲任,托疮毒。巴戟天功效:补肾阳,强筋骨,祛风湿:此外,兼益精血。","prompt":"具有补肾阳,益精血功效的药组是","sharedOptions":{"A":"补骨脂,益智仁","B":"淫羊盐,巴戟天","C":"沙苑子,淫羊盐","D":"杜仲,补骨脂","E":"鹿茸,巴戟天"},"groupId":"2018-U0-B1-151-152","groupStart":151,"groupEnd":152},{"id":"2018-U0-152","unit":0,"number":152,"type":"B1","stem":"具有补肾阳,祛风湿功效的药组是","options":{"A":"补骨脂,益智仁","B":"淫羊盐,巴戟天","C":"沙苑子,淫羊盐","D":"杜仲,补骨脂","E":"鹿茸,巴戟天"},"answer":"B","explanation":"巴戟天功效:补肾阳,强筋骨,祛风湿(兼益精血)。主治病证:阳痿遗精,宫冷不孕,月经不调,少腹冷痛,风湿痹痛,筋骨痿软。淫羊盐功效:补肾阳,强筋骨,祛风湿。","prompt":"具有补肾阳,祛风湿功效的药组是","sharedOptions":{"A":"补骨脂,益智仁","B":"淫羊盐,巴戟天","C":"沙苑子,淫羊盐","D":"杜仲,补骨脂","E":"鹿茸,巴戟天"},"groupId":"2018-U0-B1-151-152","groupStart":151,"groupEnd":152},{"id":"2018-U0-153","unit":0,"number":153,"type":"B1","stem":"阿胶的主治病症是","options":{"A":"阴虚燥咳","B":"气虚自汗","C":"胃痰呕吐","D":"湿热泻痢","E":"风寒湿痹"},"answer":"A","explanation":"阿胶功效:补血滋阴,润燥,止血。应用:.血虚萎黄,眩晕,心悸,肌痿无力。@劳嗽咯血,吐血尿血,便血崩漏,妊娠胎漏。@肺燥咳嗽。@热病伤阴,心烦失眠,阴虚风动,手足抽搐。因此答案选A。秃到秃头","prompt":"阿胶的主治病症是","sharedOptions":{"A":"阴虚燥咳","B":"气虚自汗","C":"胃痰呕吐","D":"湿热泻痢","E":"风寒湿痹"},"groupId":"2018-U0-B1-153-154","groupStart":153,"groupEnd":154},{"id":"2018-U0-154","unit":0,"number":154,"type":"B1","stem":"黄芪的主治病症是","options":{"A":"阴虚燥咳","B":"气虚自汗","C":"胃痰呕吐","D":"湿热泻痢","E":"风寒湿痹"},"answer":"B","explanation":"黄芪功效:补气升阳,固表止汗,利水消肿,托疮生肌。应用:.脾虚气陷证。@肺气虚证。@气虚自汗。@内热消渴,血虚萎黄。0半身不遂,痹痛麻木。@气血亏虚,疮疡难溃难腐,或溃久不敛。","prompt":"黄芪的主治病症是","sharedOptions":{"A":"阴虚燥咳","B":"气虚自汗","C":"胃痰呕吐","D":"湿热泻痢","E":"风寒湿痹"},"groupId":"2018-U0-B1-153-154","groupStart":153,"groupEnd":154},{"id":"2018-U0-155","unit":0,"number":155,"type":"B1","stem":"兼补肺,胃之阴的药物是","options":{"A":"鳖甲","B":"石斛","C":"百合","D":"北沙参","E":"何首乌"},"answer":"D","explanation":"北沙参性能:甘、微苦、微寒。归肺、胃经。功效:养阴清肺,益胃生津。","prompt":"兼补肺,胃之阴的药物是","sharedOptions":{"A":"鳖甲","B":"石斛","C":"百合","D":"北沙参","E":"何首乌"},"groupId":"2018-U0-B1-155-156","groupStart":155,"groupEnd":156},{"id":"2018-U0-156","unit":0,"number":156,"type":"B1","stem":"兼补肝,肾之阴的药物是","options":{"A":"鳖甲","B":"石斛","C":"百合","D":"北沙参","E":"何首乌"},"answer":"E","explanation":"何首乌功效:制用:补肝肾,益精血,乌须发,强筋骨,化浊降脂。生用:解毒,消痈,截疟,润肠通便。","prompt":"兼补肝,肾之阴的药物是","sharedOptions":{"A":"鳖甲","B":"石斛","C":"百合","D":"北沙参","E":"何首乌"},"groupId":"2018-U0-B1-155-156","groupStart":155,"groupEnd":156},{"id":"2018-U0-157","unit":0,"number":157,"type":"B1","stem":"流行性出血热发热期的治疗原则是","options":{"A":"控制感染,减轻外渗、改善中毒症状","B":"稳定内环境、促进利尿、导泻和透析","C":"补充血容量、纠正酸中毒和应用血管活性药","D":"维持水与电解质平衡","E":"防治继发感染"},"answer":"A","explanation":"流行性出血热发热期治疗:.抗病毒;@减轻外渗;0改善中毒症状;@预防DIC。","prompt":"流行性出血热发热期的治疗原则是","sharedOptions":{"A":"控制感染,减轻外渗、改善中毒症状","B":"稳定内环境、促进利尿、导泻和透析","C":"补充血容量、纠正酸中毒和应用血管活性药","D":"维持水与电解质平衡","E":"防治继发感染"},"groupId":"2018-U0-B1-157-158","groupStart":157,"groupEnd":158},{"id":"2018-U0-158","unit":0,"number":158,"type":"B1","stem":"流行性出血热少尿期的治疗原则是","options":{"A":"控制感染,减轻外渗、改善中毒症状","B":"稳定内环境、促进利尿、导泻和透析","C":"补充血容量、纠正酸中毒和应用血管活性药","D":"维持水与电解质平衡","E":"防治继发感染"},"answer":"B","explanation":"流行性出血热少尿期治疗以稳定机体内环境,促进利尿《导泻和透析治疗为圭。稳定机体内环境:维持水、电解质酸碱平衡。","prompt":"流行性出血热少尿期的治疗原则是","sharedOptions":{"A":"控制感染,减轻外渗、改善中毒症状","B":"稳定内环境、促进利尿、导泻和透析","C":"补充血容量、纠正酸中毒和应用血管活性药","D":"维持水与电解质平衡","E":"防治继发感染"},"groupId":"2018-U0-B1-157-158","groupStart":157,"groupEnd":158},{"id":"2018-U0-159","unit":0,"number":159,"type":"B1","stem":"内型肝炎的主要传播途径是","options":{"A":"粪一口途径","B":"输血及血液制品","C":"母婴垂直传播","D":"飞沫传播","E":"虫媒传播"},"answer":"B","explanation":"乙、丙、丁型肝炎病毒可通过传染源的各种体液排出体外,通过皮肤或黏膜的破损口(显性或隐性)进入易感者的体内而传播。丙型肝炎的传播途径以输血及血液制品为主,母婴传播相对少见。","prompt":"内型肝炎的主要传播途径是","sharedOptions":{"A":"粪一口途径","B":"输血及血液制品","C":"母婴垂直传播","D":"飞沫传播","E":"虫媒传播"},"groupId":"2018-U0-B1-159-160","groupStart":159,"groupEnd":160},{"id":"2018-U0-160","unit":0,"number":160,"type":"B1","stem":"戊型肝炎的主要传播途径是","options":{"A":"粪一口途径","B":"输血及血液制品","C":"母婴垂直传播","D":"飞沫传播","E":"虫媒传播"},"answer":"A","explanation":"甲、戊型肝炎主要经粪一口途径传播。粪便中排出的病毒通过污染手、水、食物等经口感染。","prompt":"戊型肝炎的主要传播途径是","sharedOptions":{"A":"粪一口途径","B":"输血及血液制品","C":"母婴垂直传播","D":"飞沫传播","E":"虫媒传播"},"groupId":"2018-U0-B1-159-160","groupStart":159,"groupEnd":160},{"id":"2018-U0-161","unit":0,"number":161,"type":"B1","stem":"对传染病的发生、流行及影响因素进行监测的部门是","options":{"A":"公安机关","B":"人民法院","C":"疾病预防控制机构","D":"县级以上地方政府","E":"卫生行政部门"},"answer":"C","explanation":"各级疾病预防控制机构对传染病的发生、流行以及影响其发生、流行的因素进行监测:对国外发生、国内尚未发生的传染病或者国内新发生的传染病,进行监测。","prompt":"对传染病的发生、流行及影响因素进行监测的部门是","sharedOptions":{"A":"公安机关","B":"人民法院","C":"疾病预防控制机构","D":"县级以上地方政府","E":"卫生行政部门"},"groupId":"2018-U0-B1-161-162","groupStart":161,"groupEnd":162},{"id":"2018-U0-162","unit":0,"number":162,"type":"B1","stem":"报上级部门决定后可以宣布本行政区域全部或部分为疫区的部门是","options":{"A":"公安机关","B":"人民法院","C":"疾病预防控制机构","D":"县级以上地方政府","E":"卫生行政部门"},"answer":"D","explanation":"甲类、乙类传染病暴发、流行时,县级以上地方人民政府报经上一级人民政府决定。可以宣布本行政区域部分或者全部为疫区;国务院可以决定并宣布跨省、自治区、直辖市的疫区。","prompt":"报上级部门决定后可以宣布本行政区域全部或部分为疫区的部门是","sharedOptions":{"A":"公安机关","B":"人民法院","C":"疾病预防控制机构","D":"县级以上地方政府","E":"卫生行政部门"},"groupId":"2018-U0-B1-161-162","groupStart":161,"groupEnd":162}];
